                dbm_utils.write_record(database, "alpha", b"one")  # type: ignore[arg-type]
            with self.assertRaises(TypeError):
                dbm_utils.write_record(database, b"alpha", "one")  # type: ignore[arg-type]
        finally:
            dbm_utils.close(database)

