    def test_invalid_channels(self) -> None:
        with self.assertRaises(ValueError):
            rgb_to_hsl(256, 0, 0)
        with self.assertRaises(TypeError):
            rgb_to_hsl("a", 0, 0)  # type: ignore[arg-type]


