cat > "$OUTPUT_DIR/cli_utils.py" <<'CLI_UTILS'
"""Command-line interface utility functions.

This module provides helpers for building simple command-line applications:
creating an :mod:`argparse` parser with standard options, parsing arguments,
and wrapping a main function so it returns consistent process exit codes.
"""

from __future__ import annotations

import argparse
from functools import wraps
from typing import Callable, List, Optional

__all__: List[str] = [
    "create_parser",
    "parse_arguments",
    "main_wrapper",
]


def create_parser(
    prog: str,
    description: str,
    epilog: Optional[str] = None,
) -> argparse.ArgumentParser:
    """Create an ArgumentParser with standard options.

    Args:
        prog: The name of the program.
        description: A brief description of the program.
        epilog: Optional text displayed after the argument help.

    Returns:
        An ArgumentParser configured with ``--verbose`` and ``--version``.

    Examples:
        >>> parser = create_parser("my-tool", "A sample CLI tool.")
        >>> parser.prog
        'my-tool'
    """
    parser = argparse.ArgumentParser(prog=prog, description=description, epilog=epilog)
    parser.add_argument("-v", "--verbose", action="store_true", help="enable verbose output")
    parser.add_argument("--version", action="version", version=f"{prog} 0.1.0")
    return parser


def parse_arguments(
    parser: argparse.ArgumentParser,
    args: Optional[List[str]] = None,
) -> argparse.Namespace:
    """Parse command-line arguments.

    Args:
        parser: The ArgumentParser to use.
        args: Optional list of argument strings (defaults to sys.argv[1:]).

    Returns:
        The parsed arguments namespace.
    """
    return parser.parse_args(args)


def main_wrapper(func: Callable[[List[str]], int]) -> Callable[[List[str]], int]:
    """Wrap a main function to handle errors and return exit codes.

    Args:
        func: A function taking ``argv`` and returning an exit code.

    Returns:
        A wrapped function that returns ``0`` on success, ``1`` on error,
        and ``130`` on keyboard interrupt.

    Examples:
        >>> def main(argv):
        ...     print("running")
        ...     return 0
        >>> wrapped = main_wrapper(main)
        >>> wrapped([])
        running
        0
    """

    @wraps(func)
    def wrapper(argv: List[str]) -> int:
        try:
            return func(argv)
        except KeyboardInterrupt:
            return 130
        except Exception:
            return 1

    return wrapper
CLI_UTILS

# --- functools_utils.py ---
cat > "$OUTPUT_DIR/functools_utils.py" <<'FUNCTOOLS_UTILS'
"""Functional programming utilities for composing and transforming functions."""

from typing import Any, Callable, List, TypeVar

T = TypeVar("T")
R = TypeVar("R")

__all__: List[str] = [
    "compose",
    "pipe",
    "curry",
    "apply",
]


def compose(*functions: Callable[[Any], Any]) -> Callable[[Any], Any]:
    """Compose multiple functions from right to left.

    Args:
        *functions: Functions to compose. The rightmost function is applied
            first, and its result is passed to the function to its left.

    Returns:
        A composed function.

    Raises:
        ValueError: If no functions are provided.

    Examples:
        >>> def add_one(x: int) -> int:
        ...     return x + 1
        >>> def multiply_by_two(x: int) -> int:
        ...     return x * 2
        >>> composed = compose(multiply_by_two, add_one)
        >>> composed(3)
        8
    """

    if not functions:
        raise ValueError("At least one function must be provided")

    def composed(arg: Any) -> Any:
        result = arg
        for func in reversed(functions):
            result = func(result)
        return result

    return composed


def pipe(arg: Any, *functions: Callable[[Any], Any]) -> Any:
    """Apply a value through a pipeline of functions from left to right.

    Args:
        arg: The initial value to pass through the pipeline.
        *functions: Functions to apply in order.

    Returns:
        The final result after applying all functions.

    Examples:
        >>> def add_one(x: int) -> int:
        ...     return x + 1
        >>> def multiply_by_two(x: int) -> int:
        ...     return x * 2
        >>> pipe(3, add_one, multiply_by_two)
        8
    """
    result = arg
    for func in functions:
        result = func(result)
    return result


def curry(func: Callable[..., R]) -> Callable[..., Any]:
    """Curry a function to allow partial application.

    Args:
        func: The function to curry.

    Returns:
        A curried version of the function.

    Raises:
        TypeError: If ``func`` is not callable.

    Examples:
        >>> def add(x: int, y: int) -> int:
        ...     return x + y
        >>> curried = curry(add)
        >>> curried(1)(2)
        3
    """
    if not callable(func):
        raise TypeError("func must be callable")

    def curried(*args: Any, **kwargs: Any) -> Any:
        if len(args) + len(kwargs) >= func.__code__.co_argcount:
            return func(*args, **kwargs)
        return lambda *more_args, **more_kwargs: curried(*args, *more_args, **kwargs, **more_kwargs)

    return curried


def apply(func: Callable[[T], R], value: T) -> R:
    """Apply a function to a value.

    Args:
        func: The function to apply.
        value: The value to apply the function to.

    Returns:
        The result of applying the function.

    Raises:
        TypeError: If ``func`` is not callable.

    Examples:
        >>> apply(lambda x: x * 2, 5)
        10
    """
    if not callable(func):
        raise TypeError("func must be callable")
    return func(value)
FUNCTOOLS_UTILS

