cat > "$OUTPUT_DIR/array_utils.py" <<'ARRAY_UTILS'
"""Array utility functions wrapping the standard library 'array' module."""

from __future__ import annotations

from array import array
from typing import Any, Iterable

__all__: list[str] = [
    "array_create",
    "array_fromlist",
    "array_tolist",
    "array_append",
    "array_extend",
    "array_insert",
    "array_pop",
    "array_remove",
    "array_reverse",
    "array_buffer_info",
    "array_byteswap",
    "array_count",
    "array_index",
]


def array_create(typecode: str, initial: Iterable[Any] | None = None) -> array:
    """Create a new array with the given typecode."""
    if initial is None:
        return array(typecode)
    return array(typecode, initial)


def array_fromlist(typecode: str, lst: list[Any]) -> array:
    """Create an array from a list."""
    return array(typecode, lst)


def array_tolist(arr: array) -> list[Any]:
    """Convert an array to a list."""
    return list(arr)


def array_append(arr: array, item: Any) -> None:
    """Append an item to the array."""
    arr.append(item)


def array_extend(arr: array, iterable: Iterable[Any]) -> None:
    """Extend array with items from iterable."""
    arr.extend(iterable)


def array_insert(arr: array, index: int, item: Any) -> None:
    """Insert item at index in array."""
    arr.insert(index, item)


def array_pop(arr: array, index: int = -1) -> Any:
    """Remove and return item at index."""
    return arr.pop(index)


def array_remove(arr: array, item: Any) -> None:
    """Remove first occurrence of item from array."""
    arr.remove(item)


def array_reverse(arr: array) -> None:
    """Reverse array in place."""
    arr.reverse()


def array_buffer_info(arr: array) -> tuple[int, int]:
    """Return (address, length) of the buffer used by array."""
    return arr.buffer_info()


def array_byteswap(arr: array) -> None:
    """Swap bytes in place if array is not single byte."""
    arr.byteswap()


def array_count(arr: array, item: Any) -> int:
    """Count occurrences of item in array."""
    return arr.count(item)


def array_index(arr: array, item: Any, start: int = 0, stop: int | None = None) -> int:
    """Return index of first occurrence of item."""
    if stop is None:
        return arr.index(item, start)
    return arr.index(item, start, stop)
ARRAY_UTILS
# --- bisect_utils.py ---
cat > "$OUTPUT_DIR/bisect_utils.py" <<'BISECT_UTILS'
"""Bisect utility functions for binary search on sorted sequences."""

from __future__ import annotations

import bisect
from typing import Any, Sequence

__all__: list[str] = [
    "bisect_left",
    "bisect_right",
    "insort_left",
    "insort_right",
    "find_leftmost",
    "find_rightmost",
]


def bisect_left(a: Sequence[Any], x: Any, lo: int = 0, hi: int | None = None) -> int:
    return bisect.bisect_left(a, x, lo, len(a) if hi is None else hi)


def bisect_right(a: Sequence[Any], x: Any, lo: int = 0, hi: int | None = None) -> int:
    return bisect.bisect_right(a, x, lo, len(a) if hi is None else hi)


def insort_left(a: list[Any], x: Any, lo: int = 0, hi: int | None = None) -> None:
    bisect.insort_left(a, x, lo, len(a) if hi is None else hi)


def insort_right(a: list[Any], x: Any, lo: int = 0, hi: int | None = None) -> None:
    bisect.insort_right(a, x, lo, len(a) if hi is None else hi)


def find_leftmost(a: Sequence[Any], x: Any) -> int | None:
    i = bisect.bisect_left(a, x)
    if i < len(a) and a[i] == x:
        return i
    return None


def find_rightmost(a: Sequence[Any], x: Any) -> int | None:
    i = bisect.bisect_right(a, x) - 1
    if i >= 0 and a[i] == x:
        return i
    return None
BISECT_UTILS

# --- contextlib_utils.py ---
cat > "$OUTPUT_DIR/contextlib_utils.py" <<'CONTEXTLIB_UTILS'
"""Contextlib utility functions wrapping stdlib contextlib."""

from __future__ import annotations

import contextlib
import os
from contextlib import contextmanager
from typing import Any, Iterator

__all__: list[str] = [
    "suppress",
    "nullcontext",
    "closing",
    "redirect_stdout",
    "redirect_stderr",
    "chdir",
    "ExitStack",
]


def suppress(*exceptions: type[BaseException]) -> contextlib.suppress:
    return contextlib.suppress(*exceptions)


def nullcontext(enter_result: Any = None) -> contextlib.nullcontext:
    return contextlib.nullcontext(enter_result)


def closing(thing: Any) -> contextlib.closing:
    return contextlib.closing(thing)


def redirect_stdout(new_target: Any) -> contextlib.redirect_stdout:
    return contextlib.redirect_stdout(new_target)


def redirect_stderr(new_target: Any) -> contextlib.redirect_stderr:
    return contextlib.redirect_stderr(new_target)


@contextmanager
def chdir(path: Any) -> Iterator[None]:
    """Temporarily change the current working directory.

    Args:
        path: The directory to change into for the duration of the
            context. Accepts a string or any :class:`os.PathLike`
            object.

    Yields:
        None. The previous working directory is restored on exit,
        even if an exception is raised within the context.

    Raises:
        TypeError: If ``path`` is not a string or :class:`os.PathLike`.
    """
    if not isinstance(path, (str, os.PathLike)):
        raise TypeError("path must be a string or os.PathLike")
    previous = os.getcwd()
    os.chdir(os.fspath(path))
    try:
        yield
    finally:
        os.chdir(previous)


class ExitStack(contextlib.ExitStack):
    pass
CONTEXTLIB_UTILS

# --- struct_utils.py ---
cat > "$OUTPUT_DIR/struct_utils.py" <<'STRUCT_UTILS'
"""Binary struct packing and unpacking utilities.

This module provides utilities for converting between Python values and
binary :mod:`struct` format representations, with configurable byte order,
input validation, and helpers for calculating the size of a format string
and validating format strings. All functions wrap the standard library
:mod:`struct` module and raise :class:`TypeError` or :class:`ValueError`
on invalid input.
"""

from __future__ import annotations

import struct
from typing import Any, Tuple, Union

__all__: list[str] = [
    "pack",
    "unpack",
    "pack_into",
    "unpack_from",
    "calcsize",
    "is_valid_format",
]


def _require_string(value: Any, name: str) -> str:
    if not isinstance(value, str):
        raise TypeError(f"{name} must be a string")
    return value


def _validate_format(fmt: str) -> str:
    """Validate ``fmt`` as a :mod:`struct` format string and return it.

    Raises:
        TypeError: If ``fmt`` is not a string.
        ValueError: If ``fmt`` is not a valid struct format string.
    """
    _require_string(fmt, "fmt")
    try:
        struct.calcsize(fmt)
    except struct.error as exc:
        raise ValueError(f"invalid struct format string: {exc}") from exc
    return fmt


def pack(fmt: str, *values: Any) -> bytes:
    """Pack ``values`` according to ``fmt`` and return the resulting bytes.

    Args:
        fmt: A :mod:`struct` format string (e.g. ``"<iif"``).
        values: The values to pack, matching the format specifiers.

    Returns:
        The packed binary data as a :class:`bytes` object.

    Raises:
        TypeError: If ``fmt`` is not a string.
        ValueError: If ``fmt`` is invalid or the values do not match the format.

    Examples:
        >>> pack("<B", 65)
        b'A'
        >>> pack(">I", 0x41424344)
        b'ABCD'
    """
    _validate_format(fmt)
    try:
        return struct.pack(fmt, *values)
    except struct.error as exc:
        raise ValueError(f"failed to pack values for format {fmt!r}: {exc}") from exc


def unpack(fmt: str, buffer: Union[bytes, bytearray]) -> Tuple[Any, ...]:
    """Unpack ``buffer`` according to ``fmt`` and return the resulting values.

    Args:
        fmt: A :mod:`struct` format string.
        buffer: The binary data to unpack. Its length must match
            :func:`calcsize` for ``fmt``.

    Returns:
        A tuple of unpacked values.

    Raises:
        TypeError: If ``fmt`` is not a string or ``buffer`` is not bytes/bytearray.
        ValueError: If ``fmt`` is invalid or the buffer size is incorrect.

    Examples:
        >>> unpack("<B", b"A")
        (65,)
    """
    _validate_format(fmt)
    if not isinstance(buffer, (bytes, bytearray)):
        raise TypeError("buffer must be bytes or bytearray")
    try:
        return struct.unpack(fmt, buffer)
    except struct.error as exc:
        raise ValueError(f"failed to unpack buffer for format {fmt!r}: {exc}") from exc


def pack_into(fmt: str, buffer: bytearray, offset: int, *values: Any) -> None:
    """Pack ``values`` into ``buffer`` at ``offset`` according to ``fmt``.

    Args:
        fmt: A :mod:`struct` format string.
        buffer: A mutable :class:`bytearray` to pack into.
        offset: The byte offset in ``buffer`` to start writing at.
        values: The values to pack, matching the format specifiers.

    Raises:
        TypeError: If ``fmt`` is not a string, ``buffer`` is not a bytearray,
            or ``offset`` is not an integer.
        ValueError: If ``fmt`` is invalid, ``offset`` is negative, or there is
            not enough room in ``buffer``.

    Examples:
        >>> buf = bytearray(4)
        >>> pack_into(">I", buf, 0, 0x41424344)
        >>> buf
        bytearray(b'ABCD')
    """
    _validate_format(fmt)
    if not isinstance(buffer, bytearray):
        raise TypeError("buffer must be a bytearray")
    if not isinstance(offset, int) or isinstance(offset, bool):
        raise TypeError("offset must be an integer")
    if offset < 0:
        raise ValueError("offset must be non-negative")
    try:
        struct.pack_into(fmt, buffer, offset, *values)
    except struct.error as exc:
        raise ValueError(f"failed to pack into buffer for format {fmt!r}: {exc}") from exc


def unpack_from(fmt: str, buffer: Union[bytes, bytearray], offset: int = 0) -> Tuple[Any, ...]:
    """Unpack values from ``buffer`` starting at ``offset`` according to ``fmt``.

    Args:
        fmt: A :mod:`struct` format string.
        buffer: The binary data to unpack from.
        offset: The byte offset to start reading from. Defaults to 0.

    Returns:
        A tuple of unpacked values.

    Raises:
        TypeError: If ``fmt`` is not a string, ``buffer`` is not bytes/bytearray,
            or ``offset`` is not an integer.
        ValueError: If ``fmt`` is invalid, ``offset`` is negative, or there is
            not enough data in ``buffer``.

    Examples:
        >>> unpack_from(">I", b"ABCD", 0)
        (1094861636,)
    """
    _validate_format(fmt)
    if not isinstance(buffer, (bytes, bytearray)):
        raise TypeError("buffer must be bytes or bytearray")
    if not isinstance(offset, int) or isinstance(offset, bool):
        raise TypeError("offset must be an integer")
    if offset < 0:
        raise ValueError("offset must be non-negative")
    try:
        return struct.unpack_from(fmt, buffer, offset)
    except struct.error as exc:
        raise ValueError(f"failed to unpack from buffer for format {fmt!r}: {exc}") from exc


def calcsize(fmt: str) -> int:
    """Return the size in bytes of a value described by ``fmt``.

    Args:
        fmt: A :mod:`struct` format string.

    Returns:
        The number of bytes required to pack ``fmt``.

    Raises:
        TypeError: If ``fmt`` is not a string.
        ValueError: If ``fmt`` is invalid.

    Examples:
        >>> calcsize("<h")
        2
        >>> calcsize(">I")
        4
    """
    return struct.calcsize(_validate_format(fmt))


def is_valid_format(fmt: str) -> bool:
    """Return True if ``fmt`` is a valid :mod:`struct` format string.

    Args:
        fmt: The format string to validate.

    Returns:
        True if ``fmt`` is a valid struct format string, False otherwise.

    Examples:
        >>> is_valid_format("<h")
        True
        >>> is_valid_format("!!invalid!!")
        False
    """
    if not isinstance(fmt, str):
        return False
    try:
        struct.calcsize(fmt)
        return True
    except struct.error:
        return False
STRUCT_UTILS

