# --- template_utils.py ---
cat > "$OUTPUT_DIR/template_utils.py" <<'TEMPLATEUTILS'
"""String template utilities.

This module provides functions for simple string template rendering and
variable substitution. It supports both ``str.format()``-style templates
and ``string.Template``-style substitution.
"""

from __future__ import annotations

import re
from string import Template
from typing import Any, Mapping


def render_template(template: str, *args: Any, **kwargs: Any) -> str:
    """Render a template string using ``str.format()``.

    Args:
        template: The template string containing ``{placeholder}`` style
            placeholders.
        *args: Positional arguments to substitute into the template.
        **kwargs: Keyword arguments to substitute into the template.

    Returns:
        The rendered template string.

    Raises:
        TypeError: If ``template`` is not a string.
        KeyError: If a required placeholder is missing.
    """
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    return template.format(*args, **kwargs)


def substitute(
    template: str,
    mapping: Mapping[str, Any] | None = None,
    **kwargs: Any,
) -> str:
    """Substitute variables into a template using ``string.Template``.

    This is the standard substitution that raises an error if a placeholder
    is missing from the mapping.

    Args:
        template: The template string containing ``$placeholder`` or
            ``${placeholder}`` style placeholders.
        mapping: Optional mapping of placeholder names to values.
        **kwargs: Additional keyword arguments to substitute.

    Returns:
        The substituted template string.

    Raises:
        TypeError: If ``template`` is not a string.
        KeyError: If a required placeholder is missing.
    """
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if mapping is None:
        mapping = {}
    full_mapping: dict[str, Any] = dict(mapping)
    full_mapping.update(kwargs)
    return Template(template).substitute(full_mapping)


def safe_substitute(
    template: str,
    mapping: Mapping[str, Any] | None = None,
    **kwargs: Any,
) -> str:
    """Safely substitute variables into a template using ``string.Template``.

    This leaves missing placeholders unchanged instead of raising an error.

    Args:
        template: The template string containing ``$placeholder`` or
            ``${placeholder}`` style placeholders.
        mapping: Optional mapping of placeholder names to values.
        **kwargs: Additional keyword arguments to substitute.

    Returns:
        The substituted template string.

    Raises:
        TypeError: If ``template`` is not a string.
    """
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if mapping is None:
        mapping = {}
    full_mapping: dict[str, Any] = dict(mapping)
    full_mapping.update(kwargs)
    return Template(template).safe_substitute(full_mapping)


def render_from_dict(
    template: str,
    context: Mapping[str, Any] | None = None,
    default: str = "",
) -> str:
    """Render a template by substituting values from a context dictionary.

    Uses ``str.format()`` style placeholders. For missing keys, the provided
    default value is used.

    Args:
        template: The template string containing ``{placeholder}`` style
            placeholders.
        context: Dictionary containing values to substitute.
        default: Default value to use for missing placeholders.

    Returns:
        The rendered template string.

    Raises:
        TypeError: If ``template`` is not a string or if ``context`` is
            provided but not a mapping.
    """
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if context is None:
        context = {}
    if not isinstance(context, Mapping):
        raise TypeError("context must be a mapping or None")

    class DefaultFormatter(dict):
        def __missing__(self, key: str) -> str:
            return default

    try:
        return template.format_map(DefaultFormatter(context))
    except Exception:
        result = template
        for key in extract_placeholders(template):
            pattern = re.compile(r"\{" + re.escape(key) + r"(:[^}]*)?\}")
            if key in context:
                result = pattern.sub(str(context[key]), result)
            else:
                result = pattern.sub(default, result)
        return result


def has_placeholders(template: str) -> bool:
    """Check if the template contains any placeholders.

    Checks for both ``str.format()`` style (``{name}``) and
    ``string.Template`` style (``$name``, ``${name}``) placeholders.

    Args:
        template: The template string to check.

    Returns:
        ``True`` if the template contains placeholders, ``False`` otherwise.

    Raises:
        TypeError: If ``template`` is not a string.
    """
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    format_pattern = re.compile(r"\{[^}]+\}")
    if format_pattern.search(template):
        return True
    template_pattern = re.compile(r"\$[A-Za-z_][A-Za-z0-9_]*|\$\{[^}]+\}")
    if template_pattern.search(template):
        return True
    return False


def extract_placeholders(template: str) -> list[str]:
    """Extract placeholder names from a template string.

    Extracts names from both ``str.format()`` style (``{name}`` or
    ``{name:format}``) and ``string.Template`` style (``$name`` or
    ``${name}``) placeholders.

    Args:
        template: The template string to analyze.

    Returns:
        A list of placeholder names.

    Raises:
        TypeError: If ``template`` is not a string.
    """
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    placeholders: list[str] = []
    format_pattern = re.compile(r"\{([^}:]+)(?::[^}]*)?\}")
    for match in format_pattern.finditer(template):
        name = match.group(1)
        if name.isdigit():
            continue
        if name not in placeholders:
            placeholders.append(name)
    template_pattern = re.compile(r"\$\{([^}]+)\}|\$([A-Za-z_][A-Za-z0-9_]*)")
    for match in template_pattern.finditer(template):
        name = match.group(1) if match.group(1) else match.group(2)
        if name and name not in placeholders:
            placeholders.append(name)
    return placeholders
TEMPLATEUTILS
# --- semver_utils.py ---
cat > "$OUTPUT_DIR/semver_utils.py" <<'SEMVERUTILS'
"""Semantic versioning utilities.

This module provides utilities for working with semantic versions following
the Semantic Versioning specification (semver.org). Versions are expected in
``MAJOR.MINOR.PATCH`` form with optional pre-release and build metadata.
"""

from __future__ import annotations

import re
from typing import Optional, Tuple

SEMVER_RE = re.compile(
    r"^(?P<major>0|[1-9]\d*)\."
    r"(?P<minor>0|[1-9]\d*)\."
    r"(?P<patch>0|[1-9]\d*)"
    r"(?:-(?P<prerelease>[0-9A-Za-z\-]+(?:\.[0-9A-Za-z\-]+)*))?"
    r"(?:\+(?P<build>[0-9A-Za-z\-]+(?:\.[0-9A-Za-z\-]+)*))?$"
)


class SemanticVersion:
    """A parsed semantic version: MAJOR.MINOR.PATCH with optional pre-release/build."""

    def __init__(
        self,
        major: int,
        minor: int,
        patch: int,
        prerelease: Optional[str] = None,
        build: Optional[str] = None,
    ) -> None:
        if major < 0 or minor < 0 or patch < 0:
            raise ValueError("version components must be non-negative")
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

    def release_tuple(self) -> Tuple[int, int, int]:
        """Return the (major, minor, patch) release tuple."""
        return (self.major, self.minor, self.patch)

    def __str__(self) -> str:
        version = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease is not None:
            version += f"-{self.prerelease}"
        if self.build is not None:
            version += f"+{self.build}"
        return version

    def __repr__(self) -> str:
        return f"SemanticVersion({self.major}, {self.minor}, {self.patch})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, SemanticVersion):
            return NotImplemented
        return (
            self.release_tuple() == other.release_tuple()
            and self.prerelease == other.prerelease
            and self.build == other.build
        )

    def __lt__(self, other: "SemanticVersion") -> bool:
        if self.release_tuple() != other.release_tuple():
            return self.release_tuple() < other.release_tuple()
        if self.prerelease is None and other.prerelease is None:
            return False
        if self.prerelease is None:
            return False  # release > prerelease
        if other.prerelease is None:
            return True
        return _compare_prerelease(self.prerelease, other.prerelease) < 0

    def __le__(self, other: "SemanticVersion") -> bool:
        return self < other or self == other

    def __gt__(self, other: "SemanticVersion") -> bool:
        return not (self <= other)

    def __ge__(self, other: "SemanticVersion") -> bool:
        return not (self < other)

    def is_prerelease(self) -> bool:
        """Return True if this version has a pre-release tag."""
        return self.prerelease is not None


def parse_semver(version: str) -> SemanticVersion:
    """Parse a semantic version string into a :class:`SemanticVersion`.

    Raises:
        ValueError: If the string is not a valid semantic version.
    """
    if not isinstance(version, str) or not version:
        raise ValueError("version must be a non-empty string")
    match = SEMVER_RE.match(version.strip())
    if match is None:
        raise ValueError(f"invalid semantic version: {version!r}")
    return SemanticVersion(
        major=int(match.group("major")),
        minor=int(match.group("minor")),
        patch=int(match.group("patch")),
        prerelease=match.group("prerelease"),
        build=match.group("build"),
    )


def compare_semver(a: str, b: str) -> int:
    """Compare two semantic version strings. Return -1/0/1 like strcmp."""
    va = parse_semver(a)
    vb = parse_semver(b)
    if va < vb:
        return -1
    if va > vb:
        return 1
    return 0


def bump_major(version: str) -> str:
    """Bump the major version, resetting minor and patch to zero."""
    parsed = parse_semver(version)
    return str(SemanticVersion(parsed.major + 1, 0, 0))


def bump_minor(version: str) -> str:
    """Bump the minor version, resetting patch to zero."""
    parsed = parse_semver(version)
    return str(SemanticVersion(parsed.major, parsed.minor + 1, 0))


def bump_patch(version: str) -> str:
    """Bump the patch version."""
    parsed = parse_semver(version)
    return str(SemanticVersion(parsed.major, parsed.minor, parsed.patch + 1))


def is_valid_semver(version: str) -> bool:
    """Return True if the string is a valid semantic version."""
    try:
        parse_semver(version)
        return True
    except ValueError:
        return False


def _compare_prerelease(a: str, b: str) -> int:
    """Compare two pre-release identifiers per SemVer spec."""
    a_parts = a.split(".")
    b_parts = b.split(".")
    for left, right in zip(a_parts, b_parts):
        left_digit = left.isdigit()
        right_digit = right.isdigit()
        if left_digit and right_digit:
            li, ri = int(left), int(right)
            if li < ri:
                return -1
            if li > ri:
                return 1
        elif left_digit:
            return -1  # numeric identifiers have lower precedence
        elif right_digit:
            return 1
        else:
            if left < right:
                return -1
            if left > right:
                return 1
    if len(a_parts) < len(b_parts):
        return -1
    if len(a_parts) > len(b_parts):
        return 1
    return 0
SEMVERUTILS

# --- shutil_utils.py ---
cat > "$OUTPUT_DIR/shutil_utils.py" <<'SHUTIL_UTILS'
"""High-level file and directory operation utilities.

This module wraps the :mod:`shutil` standard library module to provide
convenient helpers for copying, moving, removing, and archiving files and
directory trees.
"""

from __future__ import annotations

import shutil
from pathlib import Path
from typing import Any, Optional, Union

__all__: list[str] = [
    "copy_file",
    "copy_tree",
    "move",
    "remove_tree",
    "disk_usage",
    "make_archive",
    "unpack_archive",
    "which",
]


def copy_file(src: Union[str, Path], dst: Union[str, Path]) -> str:
    """Copy a file from ``src`` to ``dst`` and return the destination path."""
    src = Path(src)
    dst = Path(dst)
    dst.parent.mkdir(parents=True, exist_ok=True)
    return str(shutil.copy2(src, dst))


def copy_tree(src: Union[str, Path], dst: Union[str, Path]) -> str:
    """Recursively copy an entire directory tree from ``src`` to ``dst``."""
    return str(shutil.copytree(src, dst, dirs_exist_ok=True))


def move(src: Union[str, Path], dst: Union[str, Path]) -> str:
    """Move a file or directory from ``src`` to ``dst``."""
    dst = Path(dst)
    dst.parent.mkdir(parents=True, exist_ok=True)
    return str(shutil.move(src, dst))


def remove_tree(path: Union[str, Path]) -> None:
    """Recursively delete a directory tree at ``path``."""
    shutil.rmtree(path)


def disk_usage(path: Union[str, Path]) -> Any:
    """Return disk usage statistics for the filesystem containing ``path``."""
    return shutil.disk_usage(path)


def make_archive(base_name: Union[str, Path], format: str, root_dir: Union[str, Path]) -> str:
    """Create an archive of ``root_dir`` and return its path."""
    return shutil.make_archive(str(base_name), format, root_dir=str(root_dir))


def unpack_archive(
    filename: Union[str, Path], extract_dir: Optional[Union[str, Path]] = None
) -> None:
    """Unpack an archive at ``filename`` into ``extract_dir``."""
    shutil.unpack_archive(filename, extract_dir=extract_dir)


def which(cmd: str) -> Optional[str]:
    """Return the path to an executable, or ``None`` if not found."""
    return shutil.which(cmd)
SHUTIL_UTILS

# --- interval_utils.py ---
cat > "$OUTPUT_DIR/interval_utils.py" <<'INTERVALUTILS'
"""Interval utilities.

This module provides utilities for working with closed numeric intervals
of the form ``(low, high)`` where ``low <= high``. It supports
normalization, containment, overlap, intersection, union/merge, length,
and validation operations.
"""

from __future__ import annotations

from typing import Optional, Tuple

Interval = Tuple[float, float]


def _is_number(value: object) -> bool:
    """Return True if *value* is a real int or float (excluding booleans)."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def normalize_interval(low: float, high: float) -> Interval:
    """Return ``(low, high)`` with ``low <= high``.

    The two endpoints are swapped when necessary so the result is always a
    valid, ordered interval.

    Args:
        low: One endpoint of the interval.
        high: The other endpoint of the interval.

    Returns:
        A tuple ``(min, max)`` representing the normalized interval.

    Raises:
        TypeError: If either endpoint is not a real number.
    """
    if not _is_number(low):
        raise TypeError(f"low must be a real number, got {type(low).__name__}")
    if not _is_number(high):
        raise TypeError(f"high must be a real number, got {type(high).__name__}")
    return (min(low, high), max(low, high))


def is_valid_interval(interval: object) -> bool:
    """Return True if *interval* is a well-formed ``(low, high)`` interval.

    A valid interval is a two-element tuple/list of real numbers with
    ``low <= high``.
    """
    if not isinstance(interval, (tuple, list)) or len(interval) != 2:
        return False
    low, high = interval
    if not _is_number(low) or not _is_number(high):
        return False
    return bool(low <= high)


def interval_contains(interval: Interval, value: float) -> bool:
    """Return True if *value* lies within the closed interval *interval*.

    Args:
        interval: A ``(low, high)`` interval.
        value: The value to test.

    Returns:
        True if ``low <= value <= high``.

    Raises:
        TypeError: If *interval* is malformed or *value* is not a real number.
        ValueError: If *interval* is not valid (``low > high``).
    """
    if not is_valid_interval(interval):
        raise ValueError(f"invalid interval: {interval!r}")
    if not _is_number(value):
        raise TypeError(f"value must be a real number, got {type(value).__name__}")
    low, high = interval
    return low <= value <= high


def interval_overlaps(a: Interval, b: Interval) -> bool:
    """Return True if intervals *a* and *b* share at least one point.

    Args:
        a: A ``(low, high)`` interval.
        b: A ``(low, high)`` interval.

    Returns:
        True if the intervals overlap (including touching at an endpoint).

    Raises:
        ValueError: If either interval is not valid.
    """
    if not is_valid_interval(a) or not is_valid_interval(b):
        raise ValueError(f"invalid interval: {a!r} or {b!r}")
    return max(a[0], b[0]) <= min(a[1], b[1])


def interval_intersection(a: Interval, b: Interval) -> Optional[Interval]:
    """Return the overlapping portion of intervals *a* and *b*.

    Args:
        a: A ``(low, high)`` interval.
        b: A ``(low, high)`` interval.

    Returns:
        The intersection interval, or ``None`` if the intervals are disjoint.

    Raises:
        ValueError: If either interval is not valid.
    """
    if not is_valid_interval(a) or not is_valid_interval(b):
        raise ValueError(f"invalid interval: {a!r} or {b!r}")
    low = max(a[0], b[0])
    high = min(a[1], b[1])
    if low > high:
        return None
    return (low, high)


def interval_union(a: Interval, b: Interval) -> Optional[Interval]:
    """Return the smallest interval covering both *a* and *b*.

    The union is only defined when the intervals overlap or touch; disjoint
    intervals return ``None``.

    Args:
        a: A ``(low, high)`` interval.
        b: A ``(low, high)`` interval.

    Returns:
        The merged interval, or ``None`` if the intervals are disjoint.

    Raises:
        ValueError: If either interval is not valid.
    """
    if not is_valid_interval(a) or not is_valid_interval(b):
        raise ValueError(f"invalid interval: {a!r} or {b!r}")
    if not interval_overlaps(a, b):
        return None
    return (min(a[0], b[0]), max(a[1], b[1]))


def merge_intervals(intervals: list[Interval]) -> list[Interval]:
    """Merge overlapping intervals into a sorted list of disjoint intervals.

    Args:
        intervals: An iterable of ``(low, high)`` intervals.

    Returns:
        A list of disjoint, sorted intervals covering the same points.

    Raises:
        TypeError: If *intervals* is not a list.
        ValueError: If any interval is not valid.
    """
    if not isinstance(intervals, list):
        raise TypeError(f"intervals must be a list, got {type(intervals).__name__}")
    for interval in intervals:
        if not is_valid_interval(interval):
            raise ValueError(f"invalid interval: {interval!r}")
    sorted_intervals = sorted(intervals, key=lambda item: (item[0], item[1]))
    merged: list[Interval] = []
    for interval in sorted_intervals:
        if merged and interval_overlaps(merged[-1], interval):
            low = merged[-1][0]
            high = max(merged[-1][1], interval[1])
            merged[-1] = (low, high)
        else:
            merged.append(interval)
    return merged


def interval_length(interval: Interval) -> float:
    """Return the length ``high - low`` of *interval*.

    Args:
        interval: A ``(low, high)`` interval.

    Returns:
        The length of the interval as a float.

    Raises:
        ValueError: If *interval* is not valid.
    """
    if not is_valid_interval(interval):
        raise ValueError(f"invalid interval: {interval!r}")
    return float(interval[1] - interval[0])
