        with warnings_utils.catch_warnings(record=True) as w:
            warnings.simplefilter("always")
            warnings.warn("hello")
            self.assertTrue(len(w) >= 1)


class TestShowAndFormat(unittest.TestCase):
    def test_formatwarning(self):
        w = DeprecationWarning("old")
