"""Unit tests for socketserver_utils."""

import socketserver
import threading
import unittest

from socketserver_utils import (
    close_server,
    create_tcp_server,
    create_udp_server,
    get_server_address,
    handle_one_request,
    is_serving,
    serve_forever,
    shutdown_server,
)


class _Handler(socketserver.BaseRequestHandler):
    def handle(self):
        pass


class TestCreateTcpServer(unittest.TestCase):
    def test_create_tcp_server_valid(self):
        server = create_tcp_server(("127.0.0.1", 0), _Handler)
        try:
            self.assertIsInstance(server, socketserver.TCPServer)
            self.assertTrue(server.allow_reuse_address)
        finally:
            close_server(server)

    def test_create_tcp_server_no_reuse_address(self):
        server = create_tcp_server(("127.0.0.1", 0), _Handler, allow_reuse_address=False)
        try:
            self.assertFalse(server.allow_reuse_address)
        finally:
            close_server(server)

    def test_create_tcp_server_invalid_address_type(self):
        with self.assertRaises(TypeError):
            create_tcp_server("not a tuple", _Handler)  # type: ignore[arg-type]

    def test_create_tcp_server_invalid_address_length(self):
        with self.assertRaises(TypeError):
            create_tcp_server(("127.0.0.1",), _Handler)  # type: ignore[arg-type]

    def test_create_tcp_server_invalid_port_type(self):
        with self.assertRaises(TypeError):
            create_tcp_server(("127.0.0.1", "8080"), _Handler)  # type: ignore[arg-type]

    def test_create_tcp_server_port_bool(self):
        with self.assertRaises(TypeError):
            create_tcp_server(("127.0.0.1", True), _Handler)  # type: ignore[arg-type]

    def test_create_tcp_server_invalid_handler(self):
        with self.assertRaises(TypeError):
            create_tcp_server(("127.0.0.1", 0), object())  # type: ignore[arg-type]


class TestCreateUdpServer(unittest.TestCase):
    def test_create_udp_server_valid(self):
        server = create_udp_server(("127.0.0.1", 0), _Handler)
        try:
            self.assertIsInstance(server, socketserver.UDPServer)
        finally:
            close_server(server)

    def test_create_udp_server_invalid_inputs(self):
        with self.assertRaises(TypeError):
            create_udp_server("not a tuple", _Handler)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            create_udp_server(("127.0.0.1", "8080"), _Handler)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            create_udp_server(("127.0.0.1", 0), object())  # type: ignore[arg-type]


class TestServerInspection(unittest.TestCase):
    def test_get_server_address_and_is_serving(self):
        server = create_tcp_server(("127.0.0.1", 0), _Handler)
        try:
            self.assertEqual(get_server_address(server), server.server_address)
            self.assertTrue(is_serving(server))
        finally:
            close_server(server)

    def test_operations_require_server(self):
        with self.assertRaises(TypeError):
            handle_one_request("not a server")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            shutdown_server("not a server")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            close_server("not a server")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            get_server_address("not a server")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            is_serving("not a server")  # type: ignore[arg-type]

    def test_serve_forever_validates_poll_interval(self):
        server = create_tcp_server(("127.0.0.1", 0), _Handler)
        try:
            with self.assertRaises(TypeError):
                serve_forever(server, poll_interval="0.5")  # type: ignore[arg-type]
            with self.assertRaises(ValueError):
                serve_forever(server, poll_interval=-1)
        finally:
            close_server(server)

    def test_serve_forever_and_shutdown(self):
        server = create_tcp_server(("127.0.0.1", 0), _Handler)
        try:
            thread = threading.Thread(target=serve_forever, args=(server,), daemon=True)
            thread.start()
            self.assertTrue(is_serving(server))
            shutdown_server(server)
            thread.join(timeout=5)
            self.assertFalse(is_serving(server))
        finally:
            close_server(server)


if __name__ == "__main__":
    unittest.main()
TESTSOCKETSERVER

# --- sqlite3_utils.py ---
cat > "$OUTPUT_DIR/sqlite3_utils.py" <<'SQLITE3_UTILS'
"""Utilities for SQLite database access (wrapping :mod:`sqlite3`).

This module provides a small, validated layer over the standard library
``sqlite3`` module for opening connections, executing statements, fetching
rows, and inspecting schema. All functions validate their inputs and raise
``TypeError`` or ``ValueError`` on invalid arguments.
"""

import sqlite3 as _sqlite3
from typing import Any, Optional, Sequence


def connect(database: str = ":memory:", *, timeout: float = 5.0) -> _sqlite3.Connection:
    """Open a connection to the SQLite database *database*.

    Args:
        database: Path to the database file, or ``":memory:"`` for an
            in-memory database.
        timeout: How long to wait for a lock before raising, in seconds.

    Returns:
        A :class:`sqlite3.Connection`.

    Raises:
        TypeError: If *database* is not a str or *timeout* is not a real
            number.
        ValueError: If *timeout* is negative.
    """
    if not isinstance(database, str):
        raise TypeError("database must be a str")
    if not isinstance(timeout, (int, float)) or isinstance(timeout, bool):
        raise TypeError("timeout must be a real number")
    if timeout < 0:
        raise ValueError("timeout must be non-negative")
    return _sqlite3.connect(database, timeout=float(timeout))


def execute(conn: _sqlite3.Connection, sql: str, params: Sequence[Any] = ()) -> _sqlite3.Cursor:
    """Execute *sql* with optional *params* on *conn* and return the cursor.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        sql: The SQL statement to execute.
        params: Optional sequence of query parameters.

    Returns:
        The :class:`sqlite3.Cursor` after execution.

    Raises:
        TypeError: If *conn* is not a Connection, *sql* is not a str, or
            *params* is not a sequence.
    """
    if not isinstance(conn, _sqlite3.Connection):
        raise TypeError("conn must be a sqlite3.Connection")
    if not isinstance(sql, str):
        raise TypeError("sql must be a str")
    if not isinstance(params, (list, tuple)):
        raise TypeError("params must be a list or tuple")
    return conn.execute(sql, tuple(params))


def executemany(
    conn: _sqlite3.Connection, sql: str, params_list: Sequence[Sequence[Any]]
) -> _sqlite3.Cursor:
    """Execute *sql* against every parameter sequence in *params_list*.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        sql: The SQL statement to execute.
        params_list: A sequence of parameter sequences, one per execution.

    Returns:
        The :class:`sqlite3.Cursor` after execution.

    Raises:
        TypeError: If *conn* is not a Connection, *sql* is not a str, or
            *params_list* is not a sequence of sequences.
    """
    if not isinstance(conn, _sqlite3.Connection):
        raise TypeError("conn must be a sqlite3.Connection")
    if not isinstance(sql, str):
        raise TypeError("sql must be a str")
    if not isinstance(params_list, (list, tuple)):
        raise TypeError("params_list must be a list or tuple")
    for params in params_list:
        if not isinstance(params, (list, tuple)):
            raise TypeError("each entry in params_list must be a list or tuple")
    return conn.executemany(sql, [tuple(params) for params in params_list])


def fetch_all(
    conn: _sqlite3.Connection, sql: str, params: Sequence[Any] = ()
) -> list[tuple[Any, ...]]:
    """Execute *sql* and return all matching rows.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        sql: The SQL SELECT statement to execute.
        params: Optional sequence of query parameters.

    Returns:
        A list of rows, each row as a tuple of column values.
    """
    cursor = execute(conn, sql, params)
    return list(cursor.fetchall())


def fetch_one(
    conn: _sqlite3.Connection, sql: str, params: Sequence[Any] = ()
) -> Optional[tuple[Any, ...]]:
    """Execute *sql* and return the first matching row, or ``None``.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        sql: The SQL SELECT statement to execute.
        params: Optional sequence of query parameters.

    Returns:
        The first row as a tuple, or ``None`` when no rows match.
    """
    cursor = execute(conn, sql, params)
    row: Optional[tuple[Any, ...]] = cursor.fetchone()
    return row


def fetch_many(
    conn: _sqlite3.Connection,
    sql: str,
    size: int,
    params: Sequence[Any] = (),
) -> list[tuple[Any, ...]]:
    """Execute *sql* and return up to *size* matching rows.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        sql: The SQL SELECT statement to execute.
        size: Maximum number of rows to return.
        params: Optional sequence of query parameters.

    Returns:
        A list of up to *size* rows.

    Raises:
        TypeError: If *size* is not an int.
        ValueError: If *size* is negative.
    """
    if not isinstance(size, int) or isinstance(size, bool):
        raise TypeError("size must be an int")
    if size < 0:
        raise ValueError("size must be non-negative")
    cursor = execute(conn, sql, params)
    return list(cursor.fetchmany(size))


def create_table(conn: _sqlite3.Connection, table: str, columns: str) -> None:
    """Create *table* with the given *columns* SQL fragment if it does not exist.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        table: Name of the table to create.
        columns: SQL column definitions (e.g. ``"id INTEGER PRIMARY KEY, name TEXT"``).

    Raises:
        TypeError: If *conn* is not a Connection or *table*/*columns* are not strs.
        ValueError: If *table* or *columns* is empty.
    """
    if not isinstance(conn, _sqlite3.Connection):
        raise TypeError("conn must be a sqlite3.Connection")
    if not isinstance(table, str):
        raise TypeError("table must be a str")
    if not isinstance(columns, str):
        raise TypeError("columns must be a str")
    if not table:
        raise ValueError("table must not be empty")
    if not columns.strip():
        raise ValueError("columns must not be empty")
    conn.execute(f"CREATE TABLE IF NOT EXISTS {table} ({columns})")
    conn.commit()


def insert_row(
    conn: _sqlite3.Connection,
    table: str,
    columns: Sequence[str],
    values: Sequence[Any],
) -> int:
    """Insert a row into *table* and return the new row id.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        table: Name of the table to insert into.
        columns: Sequence of column names.
        values: Sequence of column values, aligned with *columns*.

    Returns:
        The row id of the inserted row.

    Raises:
        TypeError: If *conn* is not a Connection or *table* is not a str, or
            *columns*/*values* are not sequences of the right kind.
        ValueError: If *table* is empty or *columns* and *values* differ in length.
    """
    if not isinstance(conn, _sqlite3.Connection):
        raise TypeError("conn must be a sqlite3.Connection")
    if not isinstance(table, str):
        raise TypeError("table must be a str")
    if not table:
        raise ValueError("table must not be empty")
    if not isinstance(columns, (list, tuple)) or not all(isinstance(c, str) for c in columns):
        raise TypeError("columns must be a list or tuple of strs")
    if not isinstance(values, (list, tuple)):
        raise TypeError("values must be a list or tuple")
    if len(columns) != len(values):
        raise ValueError("columns and values must have the same length")
    placeholders = ", ".join("?" for _ in columns)
    col_list = ", ".join(columns)
    cursor = conn.execute(
        f"INSERT INTO {table} ({col_list}) VALUES ({placeholders})",
        tuple(values),
    )
    conn.commit()
    lastrowid = cursor.lastrowid
    return int(lastrowid) if lastrowid is not None else 0


def query(conn: _sqlite3.Connection, sql: str, params: Sequence[Any] = ()) -> list[dict[str, Any]]:
    """Execute *sql* and return rows as dictionaries keyed by column name.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        sql: The SQL SELECT statement to execute.
        params: Optional sequence of query parameters.

    Returns:
        A list of row dictionaries.
    """
    cursor = execute(conn, sql, params)
    description = cursor.description
    if description is None:
        return []
    column_names = [desc[0] for desc in description]
    return [dict(zip(column_names, row)) for row in cursor.fetchall()]


def table_exists(conn: _sqlite3.Connection, table: str) -> bool:
    """Return ``True`` if *table* exists in the database.

    Args:
        conn: An open :class:`sqlite3.Connection`.
        table: Name of the table to check.

    Returns:
        ``True`` when a table named *table* exists, otherwise ``False``.

    Raises:
        TypeError: If *conn* is not a Connection or *table* is not a str.
        ValueError: If *table* is empty.
    """
    if not isinstance(conn, _sqlite3.Connection):
        raise TypeError("conn must be a sqlite3.Connection")
    if not isinstance(table, str):
        raise TypeError("table must be a str")
    if not table:
        raise ValueError("table must not be empty")
    cursor = conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table,))
    return cursor.fetchone() is not None
SQLITE3_UTILS

# --- tests/test_sqlite3_utils.py ---
cat > "$OUTPUT_DIR/tests/test_sqlite3_utils.py" <<'TEST_SQLITE3_UTILS'
"""Tests for sqlite3_utils."""

import sqlite3
import unittest

from sqlite3_utils import (
    connect,
    create_table,
    execute,
    executemany,
    fetch_all,
    fetch_many,
    fetch_one,
    insert_row,
    query,
    table_exists,
)


class TestSqlite3Utils(unittest.TestCase):
    def setUp(self) -> None:
        self.conn = connect(":memory:")
        create_table(
            self.conn,
            "users",
            "id INTEGER PRIMARY KEY, name TEXT NOT NULL, score REAL",
        )

    def tearDown(self) -> None:
        self.conn.close()

    def test_connect_returns_connection(self):
        self.assertIsInstance(self.conn, sqlite3.Connection)

    def test_connect_in_memory_default(self):
        conn = connect()
        try:
            self.assertIsInstance(conn, sqlite3.Connection)
        finally:
            conn.close()

    def test_connect_type_errors(self):
        with self.assertRaises(TypeError):
            connect(123)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            connect(":memory:", timeout="slow")  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            connect(":memory:", timeout=-1)

    def test_insert_row_and_fetch_one(self):
        row_id = insert_row(self.conn, "users", ["name", "score"], ["Ada", 92.5])
        self.assertEqual(row_id, 1)
        row = fetch_one(self.conn, "SELECT name, score FROM users WHERE id = ?", [1])
        self.assertEqual(row, ("Ada", 92.5))

    def test_insert_row_validation(self):
        with self.assertRaises(TypeError):
            insert_row(self.conn, 1, ["name"], ["x"])  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            insert_row(self.conn, "", ["name"], ["x"])
        with self.assertRaises(ValueError):
            insert_row(self.conn, "users", ["name", "score"], ["x"])
        with self.assertRaises(TypeError):
            insert_row(self.conn, "users", ["name"], "x")  # type: ignore[arg-type]

    def test_fetch_all(self):
        insert_row(self.conn, "users", ["name", "score"], ["Ada", 92.5])
        insert_row(self.conn, "users", ["name", "score"], ["Bob", 87.0])
        rows = fetch_all(self.conn, "SELECT name FROM users ORDER BY name")
        self.assertEqual(rows, [("Ada",), ("Bob",)])

    def test_fetch_many(self):
        insert_row(self.conn, "users", ["name", "score"], ["Ada", 92.5])
        insert_row(self.conn, "users", ["name", "score"], ["Bob", 87.0])
        insert_row(self.conn, "users", ["name", "score"], ["Cec", 91.0])
        rows = fetch_many(self.conn, "SELECT name FROM users ORDER BY name", 2)
        self.assertEqual(len(rows), 2)
        self.assertEqual(rows, [("Ada",), ("Bob",)])

    def test_fetch_many_validation(self):
        with self.assertRaises(TypeError):
            fetch_many(self.conn, "SELECT 1", "2")  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            fetch_many(self.conn, "SELECT 1", -1)

    def test_executemany(self):
        executemany(
            self.conn,
            "INSERT INTO users (name, score) VALUES (?, ?)",
            [("Ada", 92.5), ("Bob", 87.0)],
        )
        rows = fetch_all(self.conn, "SELECT name FROM users ORDER BY name")
        self.assertEqual(rows, [("Ada",), ("Bob",)])

    def test_executemany_validation(self):
        with self.assertRaises(TypeError):
            executemany(self.conn, "SELECT 1", "not-a-list")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            executemany(self.conn, "SELECT 1", [123])  # type: ignore[arg-type]

    def test_query_dicts(self):
        insert_row(self.conn, "users", ["name", "score"], ["Ada", 92.5])
        rows = query(self.conn, "SELECT id, name, score FROM users")
        self.assertEqual(rows, [{"id": 1, "name": "Ada", "score": 92.5}])

    def test_query_no_rows(self):
        rows = query(self.conn, "SELECT name FROM users WHERE id = ?", [999])
        self.assertEqual(rows, [])

    def test_table_exists(self):
        self.assertTrue(table_exists(self.conn, "users"))
        self.assertFalse(table_exists(self.conn, "nonexistent"))

    def test_table_exists_validation(self):
        with self.assertRaises(TypeError):
            table_exists(self.conn, 1)  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            table_exists(self.conn, "")

    def test_create_table_validation(self):
        with self.assertRaises(TypeError):
            create_table(self.conn, 1, "x TEXT")  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            create_table(self.conn, "", "x TEXT")
        with self.assertRaises(ValueError):
            create_table(self.conn, "t", "   ")

    def test_execute_validation(self):
        with self.assertRaises(TypeError):
            execute(None, "SELECT 1")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            execute(self.conn, 1)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            execute(self.conn, "SELECT 1", "params")  # type: ignore[arg-type]


if __name__ == "__main__":
    unittest.main()
TEST_SQLITE3_UTILS

# --- signal_utils.py ---
cat > "$OUTPUT_DIR/signal_utils.py" <<'SIGNALUTILS'
"""Signal utilities (wrapping :mod:`signal`).

This module provides helpers for working with POSIX signals using the
standard library :mod:`signal` module. All functions validate inputs and
raise :class:`TypeError` or :class:`ValueError` for invalid arguments where
applicable.
"""

from __future__ import annotations

import signal
from typing import Any, Callable, Dict, List

__all__: list[str] = [
    "alarm",
    "get_handler",
    "get_signal_name",
    "interrupt_handler",
    "is_valid_signal",
    "pause",
    "register_handler",
    "register_int_handler",
    "register_term_handler",
    "set_handler",
    "signal_info",
    "signal_names",
    "suspend_handler",
    "unregister_handler",
]


def is_valid_signal(sig: Any) -> bool:
    """Return True if ``sig`` is a valid signal number on this platform."""
    if not isinstance(sig, int):
        return False
    try:
        signal.Signals(sig)
    except ValueError:
        return False
    return True


def get_signal_name(sig: int) -> str:
    """Return the name of the signal identified by ``sig``.

    Args:
        sig: Signal number.

    Returns:
        Signal name (e.g., ``"SIGINT"``).

    Raises:
        TypeError: If ``sig`` is not an int.
        ValueError: If ``sig`` is not a valid signal number.
    """
    if not isinstance(sig, int):
        raise TypeError("sig must be an int")
    try:
        return signal.Signals(sig).name
    except ValueError as exc:
        raise ValueError(f"invalid signal number: {sig!r}") from exc


def signal_names() -> List[str]:
    """Return a sorted list of all signal names available on this platform."""
    return sorted(s.name for s in signal.Signals)


def get_handler(sig: int) -> Any:
    """Return the current handler for ``sig``.

    Args:
        sig: Signal number.

    Returns:
        The current handler (callable, ``signal.SIG_DFL``, or
        ``signal.SIG_IGN``).

    Raises:
        TypeError: If ``sig`` is not an int.
        ValueError: If ``sig`` is not a valid signal number.
    """
    if not isinstance(sig, int):
        raise TypeError("sig must be an int")
    if not is_valid_signal(sig):
        raise ValueError(f"invalid signal number: {sig!r}")
    return signal.getsignal(sig)


def set_handler(sig: int, handler: Any) -> None:
    """Set the handler for ``sig``.

    Args:
        sig: Signal number.
        handler: A callable, ``signal.SIG_DFL``, or ``signal.SIG_IGN``.

    Raises:
        TypeError: If ``sig`` is not an int.
        ValueError: If ``sig`` is not a valid signal number.
    """
    if not isinstance(sig, int):
        raise TypeError("sig must be an int")
    if not is_valid_signal(sig):
        raise ValueError(f"invalid signal number: {sig!r}")
    signal.signal(sig, handler)


def register_handler(sig: int, handler: Callable[[int, Any], Any]) -> None:
    """Register a callable ``handler`` for ``sig``.

    Args:
        sig: Signal number.
        handler: Callable invoked with (signum, frame) when the signal fires.

    Raises:
        TypeError: If ``sig`` is not an int or ``handler`` is not callable.
        ValueError: If ``sig`` is not a valid signal number.
    """
    if not isinstance(sig, int):
        raise TypeError("sig must be an int")
    if not callable(handler):
        raise TypeError("handler must be callable")
    if not is_valid_signal(sig):
        raise ValueError(f"invalid signal number: {sig!r}")
    signal.signal(sig, handler)


def register_int_handler(handler: Callable[[int, Any], Any]) -> None:
    """Register ``handler`` for ``SIGINT`` (KeyboardInterrupt).

    Raises:
        TypeError: If ``handler`` is not callable.
    """
    if not callable(handler):
        raise TypeError("handler must be callable")
    signal.signal(signal.SIGINT, handler)


def register_term_handler(handler: Callable[[int, Any], Any]) -> None:
    """Register ``handler`` for ``SIGTERM``.

    Raises:
        TypeError: If ``handler`` is not callable.
    """
    if not callable(handler):
        raise TypeError("handler must be callable")
    signal.signal(signal.SIGTERM, handler)


def interrupt_handler(signum: int, frame: Any) -> None:
    """Default ``SIGINT`` handler that raises :class:`KeyboardInterrupt`."""
    raise KeyboardInterrupt


def suspend_handler(signum: int, frame: Any) -> None:
    """No-op signal handler used to suppress or ignore a signal."""
    return None


def unregister_handler(sig: int) -> None:
    """Reset the handler for ``sig`` to its default (``SIG_DFL``).

    Args:
        sig: Signal number.

    Raises:
        TypeError: If ``sig`` is not an int.
        ValueError: If ``sig`` is not a valid signal number.
    """
    if not isinstance(sig, int):
        raise TypeError("sig must be an int")
    if not is_valid_signal(sig):
        raise ValueError(f"invalid signal number: {sig!r}")
    signal.signal(sig, signal.SIG_DFL)


def alarm(seconds: int) -> int:
    """Schedule a ``SIGALRM`` to be delivered after ``seconds`` seconds.

    Args:
        seconds: Number of seconds before the signal is delivered.

    Returns:
        The number of seconds remaining on any previously scheduled alarm.

    Raises:
        TypeError: If ``seconds`` is not an int.
        ValueError: If ``seconds`` is negative.
    """
    if not isinstance(seconds, int):
        raise TypeError("seconds must be an int")
    if seconds < 0:
        raise ValueError("seconds must be non-negative")
    return signal.alarm(seconds)


def pause() -> None:
    """Wait for the next signal to be delivered."""
    signal.pause()


def signal_info() -> Dict[str, Any]:
    """Return a dictionary with signal-related information.

    Returns:
        Dictionary with signal names, the SIGINT handler, and whether
        SIGALRM is available.
    """
    return {
        "names": signal_names(),
        "sigint_handler": signal.getsignal(signal.SIGINT),
        "alarm_available": hasattr(signal, "alarm"),
    }
SIGNALUTILS

# --- tests/test_signal_utils.py ---
cat > "$OUTPUT_DIR/tests/test_signal_utils.py" <<'TEST_SIGNAL_UTILS'
"""Unit tests for signal_utils module."""

import signal
import unittest

from signal_utils import (
    alarm,
    get_handler,
    get_signal_name,
    interrupt_handler,
    is_valid_signal,
    pause,
    register_handler,
    register_int_handler,
    register_term_handler,
    set_handler,
    signal_info,
    signal_names,
    suspend_handler,
    unregister_handler,
)

# Use SIGUSR1 when available (POSIX), otherwise fall back to SIGINT so the
# tests run on platforms with a reduced signal set.
_TEST_SIGNAL = signal.SIGUSR1 if hasattr(signal, "SIGUSR1") else signal.SIGINT


class TestSignalUtils(unittest.TestCase):
    def test_is_valid_signal(self):
        self.assertTrue(is_valid_signal(signal.SIGINT))
        self.assertFalse(is_valid_signal("SIGINT"))
        self.assertFalse(is_valid_signal(999999))
        self.assertFalse(is_valid_signal(None))

    def test_get_signal_name(self):
        self.assertEqual(get_signal_name(signal.SIGINT), "SIGINT")
        with self.assertRaises(TypeError):
            get_signal_name("SIGINT")  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            get_signal_name(999999)

    def test_signal_names(self):
        names = signal_names()
        self.assertIsInstance(names, list)
        self.assertIn("SIGINT", names)
        self.assertEqual(names, sorted(names))

    def test_get_handler(self):
        # The handler may have been altered by earlier tests in the same
        # process; compare against the live signal module instead of a
        # hardcoded set.
        self.assertEqual(get_handler(signal.SIGINT), signal.getsignal(signal.SIGINT))

    def test_set_handler_round_trip(self):
        original = signal.getsignal(_TEST_SIGNAL)
        try:
            set_handler(_TEST_SIGNAL, suspend_handler)
            self.assertIs(signal.getsignal(_TEST_SIGNAL), suspend_handler)
        finally:
            signal.signal(_TEST_SIGNAL, original)

    def test_register_int_handler(self):
        original = signal.getsignal(signal.SIGINT)
        try:
            register_int_handler(suspend_handler)
            self.assertIs(signal.getsignal(signal.SIGINT), suspend_handler)
        finally:
            signal.signal(signal.SIGINT, original)

    def test_register_term_handler(self):
        original = signal.getsignal(signal.SIGTERM)
        try:
            register_term_handler(suspend_handler)
            self.assertIs(signal.getsignal(signal.SIGTERM), suspend_handler)
        finally:
            signal.signal(signal.SIGTERM, original)

    def test_register_handler_type_errors(self):
        with self.assertRaises(TypeError):
            register_handler("SIGINT", suspend_handler)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            register_handler(signal.SIGINT, "not callable")  # type: ignore[arg-type]

    def test_interrupt_handler(self):
        with self.assertRaises(KeyboardInterrupt):
            interrupt_handler(signal.SIGINT, None)

    def test_suspend_handler(self):
        self.assertIsNone(suspend_handler(signal.SIGINT, None))

    def test_alarm(self):
        self.assertEqual(alarm(0), 0)

    def test_alarm_type_errors(self):
        with self.assertRaises(TypeError):
            alarm("5")  # type: ignore[arg-type]
        with self.assertRaises(ValueError):
            alarm(-1)

    def test_pause_is_callable(self):
        self.assertTrue(callable(pause))

    def test_signal_info(self):
        info = signal_info()
        self.assertIsInstance(info, dict)
        self.assertIn("names", info)
        self.assertIn("sigint_handler", info)
        self.assertIn("alarm_available", info)

    def test_unregister_handler(self):
        original = signal.getsignal(_TEST_SIGNAL)
        try:
            unregister_handler(_TEST_SIGNAL)
            self.assertIs(signal.getsignal(_TEST_SIGNAL), signal.SIG_DFL)
        finally:
            signal.signal(_TEST_SIGNAL, original)


if __name__ == "__main__":
    unittest.main()
TEST_SIGNAL_UTILS

# --- pkgutil_utils.py ---
cat > "$OUTPUT_DIR/pkgutil_utils.py" <<'PKGUTIL_UTILS'
"""Utilities for package and module discovery (wrapping :mod:`pkgutil`).

This module provides a small, validated layer over the standard library
``pkgutil`` module for locating modules inside packages, reading package data
files, and resolving importable names. All functions validate their inputs and
raise ``TypeError`` on invalid arguments.
"""

from __future__ import annotations

import importlib.util
import pkgutil
from typing import Any, Callable, Sequence

__all__ = [
    "iter_modules",
    "walk_packages",
    "get_data",
    "read_text",
    "resolve_name",
    "iter_importers",
    "extend_path",
    "find_spec",
]


def _validate_path(path: Sequence[str] | None) -> list[str] | None:
    """Validate and normalize a sequence of search directories.

    Args:
        path: Optional sequence of directory paths to search.

    Returns:
        A list of directory paths, or None when *path* is None.

    Raises:
        TypeError: If *path* is not None and not a sequence of strings.
    """
    if path is None:
        return None
    if isinstance(path, (str, bytes)):
        raise TypeError("path must be a sequence of strings, not a single string")
    if not isinstance(path, Sequence):
        raise TypeError("path must be a sequence of strings")
    for entry in path:
        if not isinstance(entry, str):
            raise TypeError("path entries must be strings")
    return list(path)


def _validate_prefix(prefix: str) -> str:
    """Validate a module name prefix.

    Args:
        prefix: Prefix prepended to discovered module names.

    Returns:
        The validated prefix.

    Raises:
        TypeError: If *prefix* is not a string.
    """
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a str")
    return prefix


def iter_modules(
    path: Sequence[str] | None = None, prefix: str = ""
) -> list[tuple[str, bool]]:
    """List the modules found in *path*.

    Args:
        path: Optional sequence of directories to search. When None the
            current ``sys.path`` is searched.
        prefix: Prefix prepended to every discovered module name.

    Returns:
        A list of ``(name, is_package)`` tuples.

    Raises:
        TypeError: If *path* is not a sequence of strings or *prefix* is not
            a string.
    """
    directories = _validate_path(path)
    _validate_prefix(prefix)
    return [(info.name, info.ispkg) for info in pkgutil.iter_modules(directories, prefix)]


def walk_packages(
    path: Sequence[str] | None = None,
    prefix: str = "",
    onerror: Callable[[str], None] | None = None,
) -> list[tuple[str, bool]]:
    """Recursively list the modules and sub-packages found in *path*.

    Args:
        path: Optional sequence of directories to search. When None the
            current ``sys.path`` is searched.
        prefix: Prefix prepended to every discovered module name.
        onerror: Optional callable invoked with the name of a package that
            could not be imported.

    Returns:
        A list of ``(name, is_package)`` tuples for every discovered module.

    Raises:
        TypeError: If *path* is not a sequence of strings, *prefix* is not a
            string, or *onerror* is not callable.
    """
    directories = _validate_path(path)
    _validate_prefix(prefix)
    if onerror is not None and not callable(onerror):
        raise TypeError("onerror must be callable")
    found = pkgutil.walk_packages(directories, prefix, onerror)
    return [(info.name, info.ispkg) for info in found]


def get_data(package: str, resource: str) -> bytes:
    """Read a data file shipped inside *package*.

    Args:
        package: Name of the package that contains the resource.
        resource: Name of the resource file inside the package.

    Returns:
        The raw bytes of the resource.

    Raises:
        TypeError: If *package* or *resource* is not a string.
        OSError: If the resource cannot be found.
    """
    if not isinstance(package, str):
        raise TypeError("package must be a str")
    if not isinstance(resource, str):
        raise TypeError("resource must be a str")
    data = pkgutil.get_data(package, resource)
    if data is None:
        raise OSError(f"resource {resource!r} not found in package {package!r}")
    return data


def read_text(
    package: str, resource: str, encoding: str = "utf-8", errors: str = "strict"
) -> str:
    """Read a data file shipped inside *package* and decode it as text.

    Args:
        package: Name of the package that contains the resource.
        resource: Name of the resource file inside the package.
        encoding: Text encoding used to decode the resource.
        errors: Error handling scheme used when decoding fails.

    Returns:
        The decoded contents of the resource.

    Raises:
        TypeError: If any argument is not a string.
        OSError: If the resource cannot be found.
        UnicodeDecodeError: If the resource cannot be decoded.
    """
    if not isinstance(encoding, str):
        raise TypeError("encoding must be a str")
    if not isinstance(errors, str):
        raise TypeError("errors must be a str")
    return get_data(package, resource).decode(encoding, errors)


def resolve_name(name: str) -> Any:
    """Resolve a dotted name to the module or attribute it refers to.

    Args:
        name: Dotted module name, optionally with a ``:attr`` suffix.

    Returns:
        The resolved object, usually a module.

    Raises:
        TypeError: If *name* is not a string.
        ValueError: If *name* is not a valid dotted name.
        ImportError: If the name cannot be imported.
    """
    if not isinstance(name, str):
        raise TypeError("name must be a str")
    return pkgutil.resolve_name(name)


def iter_importers(fullname: str = "") -> list[Any]:
    """Return the meta path finders that would be consulted for *fullname*.

    Args:
        fullname: Fully qualified module name to find importers for.

    Returns:
        A list of importer objects, in the order they are consulted.

    Raises:
        TypeError: If *fullname* is not a string.
    """
    if not isinstance(fullname, str):
        raise TypeError("fullname must be a str")
    return list(pkgutil.iter_importers(fullname))


def extend_path(path: list[str], name: str) -> list[str]:
    """Extend a package ``__path__`` with the directories of a namespace package.

    Args:
        path: Existing package path entries.
        name: Name of the package being extended.

    Returns:
        The extended list of package path entries.

    Raises:
        TypeError: If *path* is not a list of strings or *name* is not a
            string.
    """
    if not isinstance(path, list) or not all(isinstance(entry, str) for entry in path):
        raise TypeError("path must be a list of strings")
    if not isinstance(name, str):
        raise TypeError("name must be a str")
    return pkgutil.extend_path(path, name)


def find_spec(name: str) -> Any:
    """Return the import spec for the module named *name*.

    This replaces the deprecated :func:`pkgutil.get_loader` helper and
    returns ``None`` when the module cannot be found.

    Args:
        name: Name of the module to look up.

    Returns:
        The module spec, or None when the module cannot be found.

    Raises:
        TypeError: If *name* is not a string.
    """
    if not isinstance(name, str):
        raise TypeError("name must be a str")
    return importlib.util.find_spec(name)
PKGUTIL_UTILS

# --- tests/test_pkgutil_utils.py ---
cat > "$OUTPUT_DIR/tests/test_pkgutil_utils.py" <<'TEST_PKGUTIL_UTILS'
import os
import sys
import tempfile
import unittest

from pkgutil_utils import (
    extend_path,
    find_spec,
    get_data,
    iter_importers,
    iter_modules,
    read_text,
    resolve_name,
    walk_packages,
)


class TestPkgutilUtils(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.pkg = os.path.join(self.tmp, "samplepkg")
        os.makedirs(self.pkg)
        with open(os.path.join(self.pkg, "__init__.py"), "w") as f:
            f.write("VALUE = 42\n")
        with open(os.path.join(self.pkg, "data.txt"), "w") as f:
            f.write("payload")
        with open(os.path.join(self.pkg, "mod.py"), "w") as f:
            f.write("X = 1\n")
        sub = os.path.join(self.pkg, "sub")
        os.makedirs(sub)
        with open(os.path.join(sub, "__init__.py"), "w") as f:
            f.write("")
        with open(os.path.join(sub, "leaf.py"), "w") as f:
            f.write("Y = 2\n")

    def tearDown(self):
        sys.path.remove(self.tmp) if self.tmp in sys.path else None

    def test_iter_modules_finds_modules_and_packages(self):
        found = dict(iter_modules([self.tmp]))
        self.assertEqual(found, {"samplepkg": True})
        children = dict(iter_modules([self.pkg]))
        self.assertIn("mod", children)
        self.assertFalse(children["mod"])
        self.assertIn("sub", children)
        self.assertTrue(children["sub"])

    def test_iter_modules_applies_prefix(self):
        found = dict(iter_modules([self.tmp], prefix="pkg."))
        self.assertEqual(found, {"pkg.samplepkg": True})

    def test_iter_modules_rejects_string_path(self):
        with self.assertRaises(TypeError):
            iter_modules(self.tmp)

    def test_iter_modules_rejects_non_string_entries(self):
        with self.assertRaises(TypeError):
            iter_modules([1])

    def test_iter_modules_rejects_non_string_prefix(self):
        with self.assertRaises(TypeError):
            iter_modules([self.pkg], prefix=5)


    def test_walk_packages_finds_nested_modules(self):
        names = dict(walk_packages([self.pkg], prefix="samplepkg."))
        self.assertIn("samplepkg.mod", names)
        self.assertIn("samplepkg.sub", names)
        self.assertIn("samplepkg.sub.leaf", names)
        self.assertTrue(names["samplepkg.sub"])

    def test_walk_packages_rejects_non_callable_onerror(self):
        with self.assertRaises(TypeError):
            walk_packages([self.pkg], onerror="nope")

    def test_get_data_reads_bytes(self):
        sys.path.insert(0, self.tmp)
        try:
            data = get_data("samplepkg", "data.txt")
        finally:
            sys.path.remove(self.tmp)
        self.assertEqual(data, b"payload")

    def test_get_data_type_errors(self):
        with self.assertRaises(TypeError):
            get_data(1, "data.txt")
        with self.assertRaises(TypeError):
            get_data("samplepkg", 2)

    def test_read_text_decodes_contents(self):
        sys.path.insert(0, self.tmp)
        try:
            text = read_text("samplepkg", "data.txt")
        finally:
            sys.path.remove(self.tmp)
        self.assertEqual(text, "payload")

    def test_read_text_rejects_non_string_encoding(self):
        with self.assertRaises(TypeError):
            read_text("samplepkg", "data.txt", encoding=1)

    def test_resolve_name_returns_module(self):
        module = resolve_name("json")
        self.assertEqual(module.__name__, "json")

    def test_resolve_name_type_error(self):
        with self.assertRaises(TypeError):
            resolve_name(None)

    def test_iter_importers_returns_finders(self):
        importers = iter_importers("json")
        self.assertIsInstance(importers, list)
        self.assertTrue(len(importers) > 0)

    def test_iter_importers_type_error(self):
        with self.assertRaises(TypeError):
            iter_importers(1)

    def test_extend_path_returns_list(self):
        result = extend_path([self.tmp], "samplepkg")
        self.assertIsInstance(result, list)
        self.assertIn(self.tmp, result)

    def test_extend_path_type_errors(self):
        with self.assertRaises(TypeError):
            extend_path("not-a-list", "samplepkg")
        with self.assertRaises(TypeError):
            extend_path([], 1)

    def test_find_spec_returns_spec(self):
        spec = find_spec("json")
        self.assertIsNotNone(spec)
        self.assertEqual(spec.name, "json")

    def test_find_spec_type_error(self):
        with self.assertRaises(TypeError):
            find_spec(1)


if __name__ == "__main__":
    unittest.main()
TEST_PKGUTIL_UTILS

# --- binascii_utils.py ---
cat > "$OUTPUT_DIR/binascii_utils.py" <<'BINASCII_UTILS'
"""Binary-to-ASCII encoding and decoding utilities (wrapping :mod:`binascii`).

This module provides helpers for converting between binary data and various
ASCII encodings using the standard library :mod:`binascii` module, including
hexadecimal, Base64, UUencode, and quoted-printable encodings, as well as
CRC32, Adler32, and CRC-HQX checksums.
"""

from __future__ import annotations

import binascii as _binascii
import zlib
from typing import Union

__all__: list[str] = [
    "hexlify",
    "unhexlify",
    "b2a_base64",
    "a2b_base64",
    "b2a_uu",
    "a2b_uu",
    "b2a_qp",
    "a2b_qp",
    "crc32",
    "adler32",
    "crc_hqx",
]

_Data = Union[str, bytes]


def _to_bytes(data: _Data) -> bytes:
    """Normalize *data* to bytes, raising ``TypeError`` for unsupported types."""
    if isinstance(data, str):
        return data.encode("utf-8")
    if isinstance(data, bytes):
        return data
    raise TypeError("data must be str or bytes")


def hexlify(data: _Data) -> str:
    """Return the hexadecimal representation of *data* as a string.

    Args:
        data: Input string or bytes.

    Returns:
        Lowercase hexadecimal string representation of *data*.

    Raises:
        TypeError: If *data* is not str or bytes.
    """
    return _binascii.hexlify(_to_bytes(data)).decode("ascii")


def unhexlify(data: _Data) -> bytes:
    """Return the binary data represented by the hexadecimal string *data*.

    Args:
        data: Hexadecimal string or bytes.

    Returns:
        Binary representation of *data*.

    Raises:
        TypeError: If *data* is not str or bytes.
        ValueError: If *data* is not valid hexadecimal data.
    """
    return _binascii.unhexlify(_to_bytes(data))


def b2a_base64(data: _Data) -> str:
    """Return the Base64-encoded representation of *data* as a string.

    Args:
        data: Input string or bytes.

    Returns:
        Base64-encoded ASCII string with a trailing newline.

    Raises:
        TypeError: If *data* is not str or bytes.
    """
    return _binascii.b2a_base64(_to_bytes(data)).decode("ascii")


def a2b_base64(data: _Data) -> bytes:
    """Return the binary data represented by the Base64 string *data*.

    Args:
        data: Base64-encoded string or bytes.

    Returns:
        Decoded binary data.

    Raises:
        TypeError: If *data* is not str or bytes.
        ValueError: If *data* is not valid Base64 data.
    """
    return _binascii.a2b_base64(_to_bytes(data))


def b2a_uu(data: _Data) -> str:
    """Return the UUencode representation of *data* as a string.

    Args:
        data: Input string or bytes.

    Returns:
        UUencode-encoded ASCII string.

    Raises:
        TypeError: If *data* is not str or bytes.
    """
    return _binascii.b2a_uu(_to_bytes(data)).decode("ascii")


def a2b_uu(data: _Data) -> bytes:
    """Return the binary data represented by the UUencode string *data*.

    Args:
        data: UUencode-encoded string or bytes.

    Returns:
        Decoded binary data.

    Raises:
        TypeError: If *data* is not str or bytes.
        ValueError: If *data* is not valid UUencode data.
    """
    return _binascii.a2b_uu(_to_bytes(data))


def b2a_qp(data: _Data) -> str:
    """Return the quoted-printable representation of *data* as a string.

    Args:
        data: Input string or bytes.

    Returns:
        Quoted-printable-encoded ASCII string.

    Raises:
        TypeError: If *data* is not str or bytes.
    """
    return _binascii.b2a_qp(_to_bytes(data)).decode("ascii")


def a2b_qp(data: _Data) -> bytes:
    """Return the binary data represented by the quoted-printable string *data*.

    Args:
        data: Quoted-printable-encoded string or bytes.

    Returns:
        Decoded binary data.

    Raises:
        TypeError: If *data* is not str or bytes.
        ValueError: If *data* is not valid quoted-printable data.
    """
    return _binascii.a2b_qp(_to_bytes(data))


def crc32(data: _Data) -> int:
    """Return the CRC32 checksum of *data* as an unsigned 32-bit integer.

    Args:
        data: Input string or bytes.

    Returns:
        CRC32 checksum of *data*.

    Raises:
        TypeError: If *data* is not str or bytes.
    """
    return _binascii.crc32(_to_bytes(data)) & 0xFFFFFFFF


def adler32(data: _Data) -> int:
    """Return the Adler32 checksum of *data* as an unsigned 32-bit integer.

    Args:
        data: Input string or bytes.

    Returns:
        Adler32 checksum of *data*.

    Raises:
        TypeError: If *data* is not str or bytes.
    """
    return zlib.adler32(_to_bytes(data)) & 0xFFFFFFFF


def crc_hqx(data: _Data, value: int = 0) -> int:
    """Return the CRC-HQX checksum of *data* with the given initial *value*.

    Args:
        data: Input string or bytes.
        value: Initial CRC value (defaults to 0).

    Returns:
        CRC-HQX checksum of *data*.

    Raises:
        TypeError: If *data* is not str or bytes or *value* is not an int.
    """
    if not isinstance(value, int) or isinstance(value, bool):
        raise TypeError("value must be an int")
    return _binascii.crc_hqx(_to_bytes(data), value)
