        self.assertEqual(opts, [("-a", "val")])
        self.assertEqual(args, ["pos"])

    def test_getopt_long(self):
        opts, args = getopt(["--alpha", "val"], "", ["alpha="])
        self.assertEqual(opts, [("--alpha", "val")])
