    inp = io.BytesIO(b"hi = there")
    out = io.BytesIO()
    encode_file(inp, out)
    out.seek(0)
    inp2 = io.BytesIO(out.read())
    out2 = io.BytesIO()
    decode_file(inp2, out2)
    assert out2.getvalue() == b"hi = there"
