cat > "$OUTPUT_DIR/tests/test_shelve_utils.py" <<'TEST_SHELVE_UTILS'
"""Tests for shelve_utils."""

import os
import shutil
import tempfile
import unittest

from shelve_utils import (
    close,
    contains,
    delete,
    get,
    is_shelf,
    keys,
    open_shelf,
    set_value,
    sync,
)


class TestShelveUtils(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.path = os.path.join(self.tmp, "shelf")

    def tearDown(self):
        shutil.rmtree(self.tmp, ignore_errors=True)

    def test_open_shelf_creates_database(self):
        shelf = open_shelf(self.path)
        try:
            self.assertTrue(is_shelf(shelf))
            self.assertTrue(os.path.exists(self.path) or len(os.listdir(self.tmp)) > 0)
        finally:
            close(shelf)

    def test_open_shelf_rejects_non_string_filename(self):
        with self.assertRaises(TypeError):
            open_shelf(123)

    def test_open_shelf_rejects_invalid_flag(self):
        with self.assertRaises(ValueError):
            open_shelf(self.path, flag="x")

    def test_open_shelf_accepts_explicit_protocol(self):
        shelf = open_shelf(self.path, protocol=2)
        try:
            set_value(shelf, "a", 1)
            self.assertEqual(get(shelf, "a"), 1)
        finally:
            close(shelf)

    def test_set_value_and_get(self):
        shelf = open_shelf(self.path)
        try:
            set_value(shelf, "name", "kilo")
            set_value(shelf, "count", 3)
            self.assertEqual(get(shelf, "name"), "kilo")
            self.assertEqual(get(shelf, "count"), 3)
        finally:
            close(shelf)

    def test_get_returns_default_for_missing_key(self):
        shelf = open_shelf(self.path)
        try:
            self.assertIsNone(get(shelf, "missing"))
            self.assertEqual(get(shelf, "missing", "fallback"), "fallback")
        finally:
            close(shelf)

    def test_get_rejects_non_string_key(self):
        shelf = open_shelf(self.path)
        try:
            with self.assertRaises(TypeError):
                get(shelf, 1)
        finally:
            close(shelf)

    def test_set_value_rejects_non_string_key(self):
        shelf = open_shelf(self.path)
        try:
            with self.assertRaises(TypeError):
                set_value(shelf, 1, "value")
        finally:
            close(shelf)

    def test_keys_lists_stored_keys(self):
        shelf = open_shelf(self.path)
        try:
            set_value(shelf, "a", 1)
            set_value(shelf, "b", 2)
            self.assertEqual(sorted(keys(shelf)), ["a", "b"])
        finally:
            close(shelf)

    def test_contains_reports_membership(self):
        shelf = open_shelf(self.path)
        try:
            set_value(shelf, "present", 1)
            self.assertTrue(contains(shelf, "present"))
            self.assertFalse(contains(shelf, "absent"))
        finally:
            close(shelf)

    def test_contains_rejects_non_string_key(self):
        shelf = open_shelf(self.path)
        try:
            with self.assertRaises(TypeError):
                contains(shelf, 1)
        finally:
            close(shelf)

    def test_delete_removes_key(self):
        shelf = open_shelf(self.path)
        try:
            set_value(shelf, "gone", 1)
            delete(shelf, "gone")
            self.assertFalse(contains(shelf, "gone"))
        finally:
            close(shelf)

    def test_delete_missing_key_raises_key_error(self):
        shelf = open_shelf(self.path)
        try:
            with self.assertRaises(KeyError):
                delete(shelf, "nope")
        finally:
            close(shelf)

    def test_delete_rejects_non_string_key(self):
        shelf = open_shelf(self.path)
        try:
            with self.assertRaises(TypeError):
                delete(shelf, 1)
        finally:
            close(shelf)

    def test_values_persist_across_sessions(self):
        shelf = open_shelf(self.path)
        try:
            set_value(shelf, "persisted", [1, 2, 3])
        finally:
            close(shelf)

        shelf = open_shelf(self.path)
        try:
            self.assertEqual(get(shelf, "persisted"), [1, 2, 3])
        finally:
            close(shelf)

    def test_sync_with_writeback(self):
        shelf = open_shelf(self.path, writeback=True)
        try:
            set_value(shelf, "cached", "value")
            sync(shelf)
            self.assertEqual(get(shelf, "cached"), "value")
        finally:
            close(shelf)

    def test_sync_rejects_object_without_sync(self):
        with self.assertRaises(AttributeError):
            sync(object())

    def test_close_rejects_object_without_close(self):
        with self.assertRaises(AttributeError):
            close(object())

    def test_is_shelf_rejects_other_objects(self):
        self.assertFalse(is_shelf({}))
        self.assertFalse(is_shelf(None))


if __name__ == "__main__":
    unittest.main()
TEST_SHELVE_UTILS

# --- zlib_utils.py ---
cat > "$OUTPUT_DIR/zlib_utils.py" <<'ZLIB_UTILS'
"""Zlib compression and checksum utilities wrapping the standard library ``zlib``.

The :mod:`zlib` module provides DEFLATE compression and the CRC-32 and Adler-32
checksums. This module wraps those primitives in a small, validated layer: every
helper checks its arguments and raises ``TypeError`` on invalid input.
"""

from __future__ import annotations

import zlib as _zlib
from typing import Any

__all__: list[str] = [
    "zlib_compress",
    "zlib_decompress",
    "zlib_compressobj",
    "zlib_decompressobj",
    "zlib_crc32",
    "zlib_adler32",
]


def zlib_compress(data: bytes, level: int = -1) -> bytes:
    """
    Compress bytes using zlib DEFLATE.

    Args:
        data: Bytes to compress.
        level: Compression level (-1 default, 0 none, 9 max).

    Returns:
        The compressed bytes.

    Raises:
        TypeError: If data is not bytes.
    """
    if not isinstance(data, (bytes, bytearray)):
        raise TypeError(f"data must be bytes, got {type(data).__name__}")
    return _zlib.compress(bytes(data), level=level)


def zlib_decompress(data: bytes) -> bytes:
    """
    Decompress zlib-compressed bytes.

    Args:
        data: Compressed bytes.

    Returns:
        The decompressed bytes.

    Raises:
        TypeError: If data is not bytes.
    """
    if not isinstance(data, (bytes, bytearray)):
        raise TypeError(f"data must be bytes, got {type(data).__name__}")
    return _zlib.decompress(bytes(data))


def zlib_compressobj(level: int = -1) -> Any:
    """
    Create a compression object for streaming compression.

    Args:
        level: Compression level (-1 default, 0 none, 9 max).

    Returns:
        A ``zlib.compressobj`` instance.
    """
    return _zlib.compressobj(level=level)


def zlib_decompressobj() -> Any:
    """
    Create a decompression object for streaming decompression.

    Returns:
        A ``zlib.decompressobj`` instance.
    """
    return _zlib.decompressobj()


def zlib_crc32(data: bytes) -> int:
    """
    Compute the CRC-32 checksum of data.

    Args:
        data: Bytes to checksum.

    Returns:
        The CRC-32 checksum as an unsigned integer.

    Raises:
        TypeError: If data is not bytes.
    """
    if not isinstance(data, (bytes, bytearray)):
        raise TypeError(f"data must be bytes, got {type(data).__name__}")
    return _zlib.crc32(bytes(data)) & 0xFFFFFFFF


def zlib_adler32(data: bytes) -> int:
    """
    Compute the Adler-32 checksum of data.

    Args:
        data: Bytes to checksum.

    Returns:
        The Adler-32 checksum as an unsigned integer.

    Raises:
        TypeError: If data is not bytes.
    """
    if not isinstance(data, (bytes, bytearray)):
        raise TypeError(f"data must be bytes, got {type(data).__name__}")
    return _zlib.adler32(bytes(data)) & 0xFFFFFFFF
ZLIB_UTILS

# --- tests/test_zlib_utils.py ---
cat > "$OUTPUT_DIR/tests/test_zlib_utils.py" <<'TEST_ZLIB_UTILS'
"""Tests for zlib_utils."""

import unittest

from zlib_utils import (
    zlib_adler32,
    zlib_compress,
    zlib_compressobj,
    zlib_crc32,
    zlib_decompress,
    zlib_decompressobj,
)


class TestZlibUtils(unittest.TestCase):
    def test_compress_decompress_roundtrip(self):
        data = b"hello world" * 10
        compressed = zlib_compress(data)
        self.assertNotEqual(compressed, data)
        self.assertEqual(zlib_decompress(compressed), data)

    def test_compress_with_level(self):
        data = b"hello world" * 100
        compressed = zlib_compress(data, level=9)
        self.assertEqual(zlib_decompress(compressed), data)

    def test_compressobj_decompressobj_roundtrip(self):
        data = b"hello world" * 10
        co = zlib_compressobj()
        compressed = co.compress(data) + co.flush()
        do = zlib_decompressobj()
        self.assertEqual(do.decompress(compressed), data)

    def test_crc32(self):
        self.assertEqual(zlib_crc32(b"hello"), 907060870)

    def test_adler32(self):
        self.assertEqual(zlib_adler32(b"hello"), 103547413)

    def test_compress_rejects_non_bytes(self):
        with self.assertRaises(TypeError):
            zlib_compress("not bytes")  # type: ignore[arg-type]

    def test_decompress_rejects_non_bytes(self):
        with self.assertRaises(TypeError):
            zlib_decompress("not bytes")  # type: ignore[arg-type]

    def test_crc32_rejects_non_bytes(self):
        with self.assertRaises(TypeError):
            zlib_crc32("not bytes")  # type: ignore[arg-type]

    def test_adler32_rejects_non_bytes(self):
        with self.assertRaises(TypeError):
            zlib_adler32("not bytes")  # type: ignore[arg-type]


if __name__ == "__main__":
    unittest.main()
TEST_ZLIB_UTILS

