    def test_set_and_get_timeout(self):
        socket_utils.set_timeout(self.sock, 2.5)
        self.assertEqual(socket_utils.get_timeout(self.sock), 2.5)

    def test_set_timeout_none_restores_blocking_mode(self):
        socket_utils.set_timeout(self.sock, 1.0)
        socket_utils.set_timeout(self.sock, None)
        self.assertIsNone(socket_utils.get_timeout(self.sock))

    def test_set_timeout_rejects_bad_type(self):
        with self.assertRaises(TypeError):
            socket_utils.set_timeout(self.sock, "5")  # type: ignore[arg-type]

    def test_set_timeout_rejects_negative_value(self):
        with self.assertRaises(ValueError):
            socket_utils.set_timeout(self.sock, -0.5)

    def test_set_nonblocking_switches_mode(self):
        socket_utils.set_nonblocking(self.sock)
        self.assertEqual(self.sock.gettimeout(), 0.0)
        socket_utils.set_nonblocking(self.sock, False)
        self.assertIsNone(self.sock.gettimeout())

    def test_set_nonblocking_rejects_non_bool(self):
        with self.assertRaises(TypeError):
            socket_utils.set_nonblocking(self.sock, 1)  # type: ignore[arg-type]

    def test_set_reuse_address(self):
        socket_utils.set_reuse_address(self.sock)
        self.assertEqual(self.sock.getsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR), 1)

    def test_set_reuse_address_rejects_non_bool(self):
        with self.assertRaises(TypeError):
            socket_utils.set_reuse_address(self.sock, "yes")  # type: ignore[arg-type]

    def test_set_keepalive(self):
        socket_utils.set_keepalive(self.sock)
        self.assertEqual(self.sock.getsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE), 1)

    def test_set_keepalive_rejects_non_bool(self):
        with self.assertRaises(TypeError):
            socket_utils.set_keepalive(self.sock, 0)  # type: ignore[arg-type]

    def test_get_socket_name_of_unbound_socket(self):
        name = socket_utils.get_socket_name(self.sock)
        self.assertIsInstance(name, tuple)

    def test_get_peer_name_requires_socket(self):
        with self.assertRaises(TypeError):
            socket_utils.get_peer_name(None)  # type: ignore[arg-type]


class TestShutdownAndClose(unittest.TestCase):
    """Verify shutting down and closing sockets."""

    def test_shutdown_socket(self):
        left, right = socket.socketpair()
        try:
            socket_utils.shutdown_socket(left, socket_utils.SHUT_WR)
            self.assertEqual(right.recv(1), b"")
        finally:
            left.close()
            right.close()

    def test_shutdown_socket_rejects_unknown_mode(self):
        left, right = socket.socketpair()
        try:
            with self.assertRaises(ValueError):
                socket_utils.shutdown_socket(left, 99)
        finally:
            left.close()
            right.close()

    def test_shutdown_socket_requires_socket(self):
        with self.assertRaises(TypeError):
            socket_utils.shutdown_socket(object())  # type: ignore[arg-type]

    def test_close_socket(self):
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        socket_utils.close_socket(sock)
        self.assertEqual(sock.fileno(), -1)

    def test_close_socket_requires_socket(self):
        with self.assertRaises(TypeError):
            socket_utils.close_socket("not a socket")  # type: ignore[arg-type]


class TestNaming(unittest.TestCase):
    """Verify the naming helpers."""

    def test_socket_family_name(self):
        self.assertEqual(socket_utils.socket_family_name(socket.AF_INET), "AF_INET")
        self.assertEqual(socket_utils.socket_family_name(socket.AF_INET6), "AF_INET6")

    def test_socket_family_name_of_unknown_family(self):
        self.assertEqual(socket_utils.socket_family_name(9999), "UNKNOWN")

    def test_socket_family_name_rejects_non_int(self):
        with self.assertRaises(TypeError):
            socket_utils.socket_family_name("AF_INET")  # type: ignore[arg-type]

    def test_socket_type_name(self):
        self.assertEqual(socket_utils.socket_type_name(socket.SOCK_STREAM), "SOCK_STREAM")
        self.assertEqual(socket_utils.socket_type_name(socket.SOCK_DGRAM), "SOCK_DGRAM")

    def test_socket_type_name_of_unknown_type(self):
        self.assertEqual(socket_utils.socket_type_name(9999), "UNKNOWN")

    def test_socket_type_name_rejects_non_int(self):
        with self.assertRaises(TypeError):
            socket_utils.socket_type_name(None)  # type: ignore[arg-type]

    def test_error_name_of_os_error(self):
        error = OSError(errno.ECONNREFUSED, "Connection refused")
        self.assertEqual(socket_utils.error_name(error), "ECONNREFUSED")

    def test_error_name_of_code(self):
        self.assertEqual(socket_utils.error_name(errno.EAGAIN), "EAGAIN")

    def test_error_name_of_unknown_code(self):
        self.assertEqual(socket_utils.error_name(999999), "UNKNOWN")

    def test_error_name_of_os_error_without_errno(self):
        self.assertEqual(socket_utils.error_name(OSError("boom")), "UNKNOWN")

    def test_error_name_rejects_non_int(self):
        with self.assertRaises(TypeError):
            socket_utils.error_name("ECONNREFUSED")  # type: ignore[arg-type]


class TestHostInformation(unittest.TestCase):
    """Verify host related helpers."""

    def test_get_hostname(self):
        self.assertIsInstance(socket_utils.get_hostname(), str)
        self.assertTrue(socket_utils.get_hostname())

    def test_has_ipv6(self):
        self.assertIsInstance(socket_utils.has_ipv6(), bool)

    def test_is_ipv6_address(self):
        self.assertTrue(socket_utils.is_ipv6_address("::1"))
        self.assertTrue(socket_utils.is_ipv6_address("2001:db8::1"))

    def test_is_ipv6_address_rejects_ipv4(self):
        self.assertFalse(socket_utils.is_ipv6_address("127.0.0.1"))

    def test_is_ipv6_address_rejects_garbage(self):
        self.assertFalse(socket_utils.is_ipv6_address("not-an-address"))

    def test_is_ipv6_address_requires_string(self):
        with self.assertRaises(TypeError):
            socket_utils.is_ipv6_address(None)  # type: ignore[arg-type]


if __name__ == "__main__":
    unittest.main()
TEST_SOCKET_UTILS


# --- sysconfig_utils.py ---
cat > "$OUTPUT_DIR/sysconfig_utils.py" <<'SYSCONFIG_UTILS'
"""Utilities for interpreter build configuration (wrapping :mod:`sysconfig`).

The :mod:`sysconfig` module exposes the configuration variables, installation
paths and schemes that describe how the running interpreter was built and where
it keeps its files. This wrapper exposes a small, validated surface over that
functionality so callers can look up build metadata, resolve installation
paths, and inspect the available installation schemes without repeating the
usual type checks.
"""

from __future__ import annotations

import sysconfig as _sysconfig
from typing import Any, Dict, List, Optional, Tuple, cast

__all__ = [
    "get_config_vars",
    "get_config_var",
    "has_config_var",
    "list_config_var_names",
    "get_paths",
    "get_path",
    "get_platform",
    "get_python_version",
    "get_default_scheme",
    "get_preferred_scheme",
    "get_scheme_names",
    "is_python_build",
    "get_config_h_filename",
    "get_makefile_filename",
]

# The installation types understood by :func:`get_preferred_scheme`.
_INSTALLATION_TYPES = ("prefix", "home", "user")


def _require_text(value: object, name: str) -> str:
    """Return *value* when it is a string, otherwise raise ``TypeError``."""
    if not isinstance(value, str):
        raise TypeError(f"{name} must be a string, got {type(value).__name__}")
    return value


def _require_optional_text(value: object, name: str) -> Optional[str]:
    """Return *value* when it is a string or ``None``, otherwise raise ``TypeError``."""
    if value is None:
        return None
    if not isinstance(value, str):
        raise TypeError(f"{name} must be a string or None, got {type(value).__name__}")
    return value


def _require_optional_mapping(value: object, name: str) -> Optional[Dict[str, Any]]:
    """Return *value* when it is a mapping or ``None``, otherwise raise ``TypeError``."""
    if value is None:
        return None
    if not isinstance(value, dict):
        raise TypeError(f"{name} must be a dict or None, got {type(value).__name__}")
    return value


def _require_flag(value: object, name: str) -> bool:
    """Return *value* when it is a boolean, otherwise raise ``TypeError``."""
    if not isinstance(value, bool):
        raise TypeError(f"{name} must be a bool, got {type(value).__name__}")
    return value


def get_config_vars() -> Dict[str, Any]:
    """Return the configuration variables of the running interpreter.

    The variables describe the build of the interpreter, such as the compiler
    used, the platform triplet and the installation prefixes.

    Returns:
        A mapping of configuration variable names to their values.
    """
    return dict(_sysconfig.get_config_vars())


def get_config_var(name: str) -> Any:
    """Return the configuration variable registered under *name*.

    Args:
        name: Name of the configuration variable, such as ``"CC"``.

    Returns:
        The value of the variable, or ``None`` when it is not defined.

    Raises:
        TypeError: If *name* is not a string.
    """
    key = _require_text(name, "name")
    return _sysconfig.get_config_var(key)


def has_config_var(name: str) -> bool:
    """Return ``True`` when the configuration variable *name* is defined.

    Args:
        name: Name of the configuration variable.

    Returns:
        ``True`` when the variable is known to the standard library.

    Raises:
        TypeError: If *name* is not a string.
    """
    key = _require_text(name, "name")
    return key in _sysconfig.get_config_vars()


def list_config_var_names() -> List[str]:
    """Return the sorted names of the known configuration variables."""
    return sorted(_sysconfig.get_config_vars())


def get_paths(
    scheme: Optional[str] = None,
    vars: Optional[Dict[str, Any]] = None,
    expand: bool = True,
) -> Dict[str, str]:
    """Return the installation paths of the running interpreter.

    Args:
        scheme: Installation scheme to describe, or ``None`` for the default.
        vars: Additional variables that override the discovered ones.
        expand: Whether to expand the ``{variable}`` placeholders of the scheme.

    Returns:
        A mapping of path names, such as ``"stdlib"``, to their values.

    Raises:
        TypeError: If any argument has an unsupported type.
        KeyError: If *scheme* is not a known installation scheme.
    """
    scheme_name = _require_optional_text(scheme, "scheme")
    overrides = _require_optional_mapping(vars, "vars")
    should_expand = _require_flag(expand, "expand")
    if scheme_name is None:
        scheme_name = _sysconfig.get_default_scheme()
    return dict(_sysconfig.get_paths(scheme_name, overrides, should_expand))


def get_path(
    name: str,
    scheme: Optional[str] = None,
    vars: Optional[Dict[str, Any]] = None,
    expand: bool = True,
) -> str:
    """Return the installation path registered under *name*.

    Args:
        name: Name of the path, such as ``"purelib"``.
        scheme: Installation scheme to describe, or ``None`` for the default.
        vars: Additional variables that override the discovered ones.
        expand: Whether to expand the ``{variable}`` placeholders of the scheme.

    Returns:
        The configured path.

    Raises:
        TypeError: If any argument has an unsupported type.
        KeyError: If *name* is not a known path name.
    """
    key = _require_text(name, "name")
    paths = get_paths(scheme, vars, expand)
    if key not in paths:
        raise KeyError(f"unknown path name: {key!r}")
    return paths[key]


def get_platform() -> str:
    """Return the platform string of the running interpreter."""
    return _sysconfig.get_platform()


def get_python_version() -> str:
    """Return the Python version as ``"major.minor"``."""
    return _sysconfig.get_python_version()


def get_default_scheme() -> str:
    """Return the default installation scheme of the current platform."""
    return _sysconfig.get_default_scheme()


def get_preferred_scheme(scheme: str) -> str:
    """Return the preferred installation scheme for the given installation type.

    The installation type is one of ``"prefix"``, ``"home"`` or ``"user"``.
    Interpreters that do not know an installation type fall back to the
    documented POSIX defaults.

    Args:
        scheme: Installation type to resolve.

    Returns:
        The name of the preferred installation scheme.

    Raises:
        TypeError: If *scheme* is not a string.
        KeyError: If *scheme* is not a known installation type.
    """
    key = _require_text(scheme, "scheme")
    try:
        preferred = cast(str, _sysconfig.get_preferred_scheme(cast(Any, key)))
    except (KeyError, ValueError):
        if key not in _INSTALLATION_TYPES:
            raise KeyError(f"unknown installation type: {key!r}") from None
        if key == "prefix":
            return _sysconfig.get_default_scheme()
        return "posix_home" if key == "home" else "posix_user"
    return preferred


def get_scheme_names() -> Tuple[str, ...]:
    """Return the names of the known installation schemes."""
    return tuple(_sysconfig.get_scheme_names())


def is_python_build() -> bool:
    """Return ``True`` when the interpreter was built from source locally."""
    return bool(_sysconfig.is_python_build())


def get_config_h_filename() -> str:
    """Return the path of the ``pyconfig.h`` header of the interpreter."""
    return _sysconfig.get_config_h_filename()


def get_makefile_filename() -> str:
    """Return the path of the ``Makefile`` used to build the interpreter."""
    return _sysconfig.get_makefile_filename()
SYSCONFIG_UTILS

