cat > "$OUTPUT_DIR/tests/test_sysconfig_utils.py" <<'TEST_SYSCONFIG_UTILS'
"""Tests for sysconfig_utils module."""

import re
import sysconfig
import unittest

import sysconfig_utils


class TestGetConfigVars(unittest.TestCase):
    """Verify access to the interpreter configuration variables."""

    def test_get_config_vars_returns_mapping(self):
        variables = sysconfig_utils.get_config_vars()
        self.assertIsInstance(variables, dict)
        self.assertTrue(variables)

    def test_get_config_vars_contains_prefix(self):
        variables = sysconfig_utils.get_config_vars()
        self.assertIn("prefix", variables)
        self.assertIn("exec_prefix", variables)

    def test_get_config_vars_returns_a_copy(self):
        variables = sysconfig_utils.get_config_vars()
        variables["prefix"] = "/mutated"
        self.assertNotEqual(sysconfig_utils.get_config_vars()["prefix"], "/mutated")

    def test_get_config_var_of_known_name(self):
        self.assertEqual(
            sysconfig_utils.get_config_var("prefix"),
            sysconfig.get_config_var("prefix"),
        )

    def test_get_config_var_of_unknown_name(self):
        self.assertIsNone(sysconfig_utils.get_config_var("definitely-not-a-variable"))

    def test_get_config_var_requires_string(self):
        with self.assertRaises(TypeError):
            sysconfig_utils.get_config_var(1)  # type: ignore[arg-type]

    def test_has_config_var(self):
        self.assertTrue(sysconfig_utils.has_config_var("prefix"))
        self.assertFalse(sysconfig_utils.has_config_var("definitely-not-a-variable"))

    def test_has_config_var_requires_string(self):
        with self.assertRaises(TypeError):
            sysconfig_utils.has_config_var(None)  # type: ignore[arg-type]

    def test_list_config_var_names(self):
        names = sysconfig_utils.list_config_var_names()
        self.assertIsInstance(names, list)
        self.assertIn("prefix", names)
        self.assertEqual(names, sorted(names))

    def test_list_config_var_names_matches_config_vars(self):
        self.assertEqual(
            sysconfig_utils.list_config_var_names(),
            sorted(sysconfig_utils.get_config_vars()),
        )


class TestGetPaths(unittest.TestCase):
    """Verify access to the interpreter installation paths."""

    def test_get_paths_returns_mapping(self):
        paths = sysconfig_utils.get_paths()
        self.assertIsInstance(paths, dict)
        self.assertTrue(paths)

    def test_get_paths_contains_known_names(self):
        paths = sysconfig_utils.get_paths()
        for name in ("stdlib", "platstdlib", "purelib", "platlib", "include", "scripts"):
            self.assertIn(name, paths)

    def test_get_paths_without_expansion_keeps_placeholders(self):
        paths = sysconfig_utils.get_paths(expand=False)
        self.assertTrue(any("{" in value for value in paths.values()))

    def test_get_paths_with_expansion_resolves_placeholders(self):
        paths = sysconfig_utils.get_paths(expand=True)
        self.assertFalse(any("{" in value for value in paths.values()))

    def test_get_paths_supports_every_scheme(self):
        for scheme in sysconfig_utils.get_scheme_names():
            with self.subTest(scheme=scheme):
                paths = sysconfig_utils.get_paths(scheme=scheme)
                self.assertIn("purelib", paths)

    def test_get_paths_rejects_unknown_scheme(self):
        with self.assertRaises(KeyError):
            sysconfig_utils.get_paths(scheme="definitely-not-a-scheme")

    def test_get_paths_rejects_bad_types(self):
        with self.assertRaises(TypeError):
            sysconfig_utils.get_paths(scheme=1)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            sysconfig_utils.get_paths(vars=["prefix"])  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            sysconfig_utils.get_paths(expand="yes")  # type: ignore[arg-type]


class TestGetPath(unittest.TestCase):
    """Verify lookup of a single installation path."""

    def test_get_path_returns_string(self):
        self.assertIsInstance(sysconfig_utils.get_path("purelib"), str)

    def test_get_path_matches_get_paths(self):
        paths = sysconfig_utils.get_paths()
        self.assertEqual(sysconfig_utils.get_path("purelib"), paths["purelib"])

    def test_get_path_of_unknown_name(self):
        with self.assertRaises(KeyError):
            sysconfig_utils.get_path("definitely-not-a-path")

    def test_get_path_requires_string(self):
        with self.assertRaises(TypeError):
            sysconfig_utils.get_path(None)  # type: ignore[arg-type]

    def test_get_path_rejects_bad_types(self):
        with self.assertRaises(TypeError):
            sysconfig_utils.get_path("purelib", scheme=1)  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            sysconfig_utils.get_path("purelib", vars="prefix")  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            sysconfig_utils.get_path("purelib", expand=1)  # type: ignore[arg-type]


class TestInterpreterMetadata(unittest.TestCase):
    """Verify the interpreter metadata helpers."""

    def test_get_platform(self):
        platform = sysconfig_utils.get_platform()
        self.assertIsInstance(platform, str)
        self.assertTrue(platform)

    def test_get_python_version(self):
        version = sysconfig_utils.get_python_version()
        self.assertIsInstance(version, str)
        self.assertTrue(re.fullmatch(r"\d+\.\d+", version))

    def test_get_default_scheme(self):
        scheme = sysconfig_utils.get_default_scheme()
        self.assertIsInstance(scheme, str)
        self.assertIn(scheme, sysconfig_utils.get_scheme_names())

    def test_get_scheme_names(self):
        names = sysconfig_utils.get_scheme_names()
        self.assertIsInstance(names, tuple)
        self.assertTrue(names)
        self.assertIn("posix_prefix", names)

    def test_is_python_build(self):
        self.assertIsInstance(sysconfig_utils.is_python_build(), bool)

    def test_get_config_h_filename(self):
        filename = sysconfig_utils.get_config_h_filename()
        self.assertIsInstance(filename, str)
        self.assertTrue(filename)

    def test_get_makefile_filename(self):
        filename = sysconfig_utils.get_makefile_filename()
        self.assertIsInstance(filename, str)
        self.assertTrue(filename)


class TestGetPreferredScheme(unittest.TestCase):
    """Verify resolution of the preferred installation scheme."""

    def test_get_preferred_scheme_for_installation_types(self):
        for installation_type in ("prefix", "home", "user"):
            with self.subTest(installation_type=installation_type):
                scheme = sysconfig_utils.get_preferred_scheme(installation_type)
                self.assertIsInstance(scheme, str)
                self.assertTrue(scheme)

    def test_get_preferred_scheme_prefix_matches_default(self):
        self.assertEqual(
            sysconfig_utils.get_preferred_scheme("prefix"),
            sysconfig_utils.get_default_scheme(),
        )

    def test_get_preferred_scheme_of_unknown_type(self):
        with self.assertRaises(KeyError):
            sysconfig_utils.get_preferred_scheme("definitely-not-a-type")

    def test_get_preferred_scheme_requires_string(self):
        with self.assertRaises(TypeError):
            sysconfig_utils.get_preferred_scheme(None)  # type: ignore[arg-type]


if __name__ == "__main__":
    unittest.main()
TEST_SYSCONFIG_UTILS


# --- mimetypes_utils.py ---
cat > "$OUTPUT_DIR/mimetypes_utils.py" <<'MIMETYPES_UTILS'
"""Utilities for MIME type detection (wrapping :mod:`mimetypes`).

The :mod:`mimetypes` module maps file name extensions to MIME types and MIME
types back to extensions. This wrapper exposes a small, validated surface over
that functionality so callers can detect the type of a file, look up the
extensions registered for a MIME type, and register custom mappings without
repeating the usual type checks.
"""

from __future__ import annotations

import mimetypes as _mimetypes
import re
from typing import List, Optional, Sequence, Tuple

__all__ = [
    "guess_type",
    "guess_extension",
    "guess_all_extensions",
    "type_for_extension",
    "add_type",
    "init_database",
    "normalize_extension",
    "is_valid_mime_type",
    "mime_category",
    "is_text_mime_type",
]

# MIME types that carry textual payloads even though their top level type is
# not "text".
_TEXT_APPLICATION_TYPES = frozenset(
    {
        "application/json",
        "application/ld+json",
        "application/xml",
        "application/xhtml+xml",
        "application/javascript",
        "application/x-javascript",
        "application/x-www-form-urlencoded",
        "application/yaml",
        "application/x-yaml",
        "application/toml",
        "application/csv",
        "application/sql",
    }
)

# A MIME type is a "type/subtype" pair built from the characters allowed in
# an RFC 2045 token.
_MIME_TYPE_PATTERN = re.compile(
    r"^[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]*/[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]*$"
)


def _require_text(value: object, name: str) -> str:
    """Return *value* when it is a string, otherwise raise ``TypeError``."""
    if not isinstance(value, str):
        raise TypeError(f"{name} must be a string, got {type(value).__name__}")
    return value


def _require_flag(value: object, name: str) -> bool:
    """Return *value* when it is a boolean, otherwise raise ``TypeError``."""
    if not isinstance(value, bool):
        raise TypeError(f"{name} must be a bool, got {type(value).__name__}")
    return value


def guess_type(url: str, strict: bool = True) -> Tuple[Optional[str], Optional[str]]:
    """Guess the MIME type of the file behind *url*.

    Args:
        url: File name or URL to inspect.
        strict: Whether only the standard MIME types are considered.

    Returns:
        A tuple of the MIME type and the content encoding. Both entries are
        ``None`` when the type cannot be guessed.

    Raises:
        TypeError: If *url* is not a string or *strict* is not a boolean.
    """
    target = _require_text(url, "url")
    strict_flag = _require_flag(strict, "strict")
    mime_type, encoding = _mimetypes.guess_type(target, strict=strict_flag)
    return mime_type, encoding


def guess_extension(mime_type: str, strict: bool = True) -> Optional[str]:
    """Guess the file extension of *mime_type*.

    Args:
        mime_type: MIME type to look up, such as ``"text/html"``.
        strict: Whether only the standard MIME types are considered.

    Returns:
        The extension, including the leading dot, or ``None`` when the type is
        unknown.

    Raises:
        TypeError: If *mime_type* is not a string or *strict* is not a boolean.
    """
    value = _require_text(mime_type, "mime_type")
    strict_flag = _require_flag(strict, "strict")
    return _mimetypes.guess_extension(value, strict=strict_flag)


def guess_all_extensions(mime_type: str, strict: bool = True) -> List[str]:
    """Guess every file extension registered for *mime_type*.

    Args:
        mime_type: MIME type to look up, such as ``"text/html"``.
        strict: Whether only the standard MIME types are considered.

    Returns:
        The matching extensions, including the leading dot. The list is empty
        when the type is unknown.

    Raises:
        TypeError: If *mime_type* is not a string or *strict* is not a boolean.
    """
    value = _require_text(mime_type, "mime_type")
    strict_flag = _require_flag(strict, "strict")
    return list(_mimetypes.guess_all_extensions(value, strict=strict_flag))


def normalize_extension(extension: str) -> str:
    """Return *extension* in the canonical form used by the MIME database.

    The canonical form is lower case and includes the leading dot, so
    ``"HTML"`` and ``".html"`` both normalize to ``".html"``.

    Args:
        extension: Extension to normalize, with or without a leading dot.

    Returns:
        The normalized extension.

    Raises:
        TypeError: If *extension* is not a string.
        ValueError: If *extension* is empty or only whitespace.
    """
    value = _require_text(extension, "extension").strip()
    if not value:
        raise ValueError("extension must not be empty")
    if not value.startswith("."):
        value = f".{value}"
    return value.lower()


def type_for_extension(extension: str, strict: bool = True) -> Optional[str]:
    """Return the MIME type registered for *extension*.

    Args:
        extension: Extension to look up, with or without a leading dot.
        strict: Whether only the standard MIME types are considered.

    Returns:
        The MIME type, or ``None`` when the extension is unknown.

    Raises:
        TypeError: If *extension* is not a string or *strict* is not a boolean.
        ValueError: If *extension* is empty or only whitespace.
    """
    suffix = normalize_extension(extension)
    strict_flag = _require_flag(strict, "strict")
    mime_type, _encoding = _mimetypes.guess_type(f"file{suffix}", strict=strict_flag)
    return mime_type


def add_type(mime_type: str, extension: str, strict: bool = True) -> None:
    """Register *extension* as an additional suffix of *mime_type*.

    The mapping is added to the database shared by the standard library, so it
    is visible to later calls of :func:`guess_type` and :func:`guess_extension`.

    Args:
        mime_type: MIME type to register, such as ``"application/x-kilo"``.
        extension: Extension to register, with or without a leading dot.
        strict: Whether the mapping replaces an already known extension.

    Raises:
        TypeError: If an argument has an unsupported type.
        ValueError: If *extension* is empty or only whitespace.
    """
    value = _require_text(mime_type, "mime_type")
    suffix = normalize_extension(extension)
    strict_flag = _require_flag(strict, "strict")
    _mimetypes.add_type(value, suffix, strict=strict_flag)


def init_database(files: Optional[Sequence[str]] = None) -> None:
    """Initialize the MIME type database.

    Calling the function without arguments restores the platform defaults.
    Passing file names reads those files in addition to the current database.

    Args:
        files: Paths of ``mime.types`` files to read, or ``None``.

    Raises:
        TypeError: If *files* is not a sequence of strings or ``None``.
    """
    if files is None:
        _mimetypes.init()
        return
    if isinstance(files, (str, bytes)):
        raise TypeError("files must be a sequence of strings or None")
    paths: List[str] = []
    for index, item in enumerate(files):
        if not isinstance(item, str):
            raise TypeError(f"files[{index}] must be a string, got {type(item).__name__}")
        paths.append(item)
    _mimetypes.init(files=paths)


def is_valid_mime_type(mime_type: str) -> bool:
    """Return ``True`` when *mime_type* is a well formed ``type/subtype`` value.

    Args:
        mime_type: MIME type to check.

    Returns:
        ``True`` when the value consists of a type and a subtype separated by
        a slash.

    Raises:
        TypeError: If *mime_type* is not a string.
    """
    value = _require_text(mime_type, "mime_type")
    return bool(_MIME_TYPE_PATTERN.match(value))


def mime_category(mime_type: str) -> str:
    """Return the top level type of *mime_type*.

    Args:
        mime_type: MIME type to inspect, such as ``"text/html"``.

    Returns:
        The top level type in lower case, such as ``"text"``. The empty
        string is returned when the MIME type is malformed.

    Raises:
        TypeError: If *mime_type* is not a string.
    """
    value = _require_text(mime_type, "mime_type")
    if not is_valid_mime_type(value):
        return ""
    return value.split("/", 1)[0].lower()


def is_text_mime_type(mime_type: str) -> bool:
    """Return ``True`` when *mime_type* describes textual content.

    Beside the ``text/*`` types the known textual application types, such as
    ``"application/json"``, are reported as text as well.

    Args:
        mime_type: MIME type to inspect.

    Returns:
        ``True`` when the payload of the type is text.

    Raises:
        TypeError: If *mime_type* is not a string.
    """
    value = _require_text(mime_type, "mime_type")
    if mime_category(value) == "text":
        return True
    return value.lower() in _TEXT_APPLICATION_TYPES
MIMETYPES_UTILS

